## 2. content.js (Form Interception)
```javascript
// Intercept form submissions
document.addEventListener('submit', (e) => {
  const form = e.target;
  const formData = new FormData(form);
  const payload = Object.fromEntries(formData);

  // Add metadata
  const capturedData = {
    id: generateUUID(),
    timestamp: new Date().toISOString(),
    url: window.location.href,
    formName: form.name || form.id || 'unnamed',
    fields: payload,
    synced: false
  };

  // Notify background script
  chrome.runtime.sendMessage({
    action: 'captureForm',
    data: capturedData
  });

  console.log('[QA] Form captured:', capturedData);
}, true);

// Intercept XMLHttpRequest and Fetch
const originalFetch = window.fetch;
window.fetch = async function(...args) {
  const request = args[0];
  const options = args[1] || {};

  if (options.method === 'POST' && options.body) {
    try {
      const capturedData = {
        id: generateUUID(),
        timestamp: new Date().toISOString(),
        url: window.location.href,
        type: 'fetch',
        method: 'POST',
        endpoint: typeof request === 'string' ? request : request.url,
        body: options.body,
        synced: false
      };

      chrome.runtime.sendMessage({
        action: 'captureForm',
        data: capturedData
      });
    } catch (err) {
      console.error('[QA] Capture error:', err);
    }
  }

  return originalFetch.apply(this, args);
};

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}
```

## 3. background.js (Storage & Sync)
```javascript
const STORAGE_KEY = 'capturedForms';
const CONFIG_KEY = 'syncConfig';
const SYNC_INTERVAL = 60000; // 1 minute

// Initialize
chrome.runtime.onInstalled.addListener(() => {
  chrome.storage.local.set({
    [STORAGE_KEY]: [],
    [CONFIG_KEY]: {
      endpoint: 'https://your-api.example.com/qa/forms',
      enabled: true,
      batchSize: 10,
      certificatePin: null
    }
  });

  startPeriodicSync();
});

// Listen for form captures
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'captureForm') {
    saveFormData(request.data);
    sendResponse({ success: true });
  }
});

async function saveFormData(data) {
  const { [STORAGE_KEY]: forms = [] } = await chrome.storage.local.get(STORAGE_KEY);
  forms.push(data);
  await chrome.storage.local.set({ [STORAGE_KEY]: forms });
}

function startPeriodicSync() {
  setInterval(syncForms, SYNC_INTERVAL);
}

async function syncForms() {
  const { [STORAGE_KEY]: forms = [], [CONFIG_KEY]: config } = 
    await chrome.storage.local.get([STORAGE_KEY, CONFIG_KEY]);

  if (!config.enabled || !forms.length) return;

  const unsyncedForms = forms.filter(f => !f.synced);
  if (!unsyncedForms.length) return;

  const batch = unsyncedForms.slice(0, config.batchSize);

  try {
    const response = await secureFetch(config.endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ forms: batch }),
      certificatePin: config.certificatePin
    });

    if (response.ok) {
      // Mark as synced
      const syncedIds = new Set(batch.map(f => f.id));
      const updated = forms.map(f => ({
        ...f,
        synced: syncedIds.has(f.id) ? true : f.synced
      }));
      await chrome.storage.local.set({ [STORAGE_KEY]: updated });

      console.log(`[QA] Synced ${batch.length} forms`);
    }
  } catch (error) {
    console.error('[QA] Sync failed:', error);
  }
}

async function secureFetch(url, options = {}) {
  const { certificatePin, ...fetchOptions } = options;

  // Note: Certificate pinning in extensions requires native messaging
  // or service-worker level implementation. This is a placeholder.
  // For production, use a more robust approach:
  // https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto

  return fetch(url, fetchOptions);
}
```

