```javascript
const CONFIG_KEY = 'syncConfig';
const STORAGE_KEY = 'capturedForms';

document.getElementById('save').addEventListener('click', saveOptions);
document.getElementById('clearData').addEventListener('click', clearData);

async function loadOptions() {
  const { [CONFIG_KEY]: config } = await chrome.storage.local.get(CONFIG_KEY);
  if (config) {
    document.getElementById('endpoint').value = config.endpoint || '';
    document.getElementById('enabled').checked = config.enabled !== false;
    document.getElementById('batchSize').value = config.batchSize || 10;
    document.getElementById('certificatePin').value = config.certificatePin || '';
  }
}

async function saveOptions() {
  const config = {
    endpoint: document.getElementById('endpoint').value,
    enabled: document.getElementById('enabled').checked,
    batchSize: parseInt(document.getElementById('batchSize').value),
    certificatePin: document.getElementById('certificatePin').value
  };

  await chrome.storage.local.set({ [CONFIG_KEY]: config });
  document.getElementById('status').textContent = '✓ Settings saved!';
  setTimeout(() => {
    document.getElementById('status').textContent = '';
  }, 2000);
}

async function clearData() {
  if (confirm('Clear all captured form data?')) {
    await chrome.storage.local.set({ [STORAGE_KEY]: [] });
    document.getElementById('status').textContent = '✓ Data cleared!';
  }
}

loadOptions();
