/**
 * Content script - Intercepts form submissions
 * Only captures on explicitly enabled domains
 */

class FormInterceptor {
  constructor() {
    this.isEnabled = false;
    this.capturedForms = [];
    this.init();
  }

  async init() {
    // Check if capture is enabled for this domain
    const domain = window.location.hostname;
    const { enabledDomains = [] } = await chrome.storage.local.get('enabledDomains');
    this.isEnabled = enabledDomains.includes(domain);

    if (this.isEnabled) {
      this.setupInterceptors();
      console.log('[QA Capture] Form interception enabled for:', domain);
    }
  }

  setupInterceptors() {
    // Intercept form submissions
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);

    // Intercept fetch requests
    const originalFetch = window.fetch;
    window.fetch = (...args) => {
      this.captureRequest('fetch', args);
      return originalFetch.apply(this, args);
    };

    // Intercept XMLHttpRequest
    const originalOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function(...args) {
      this._requestMethod = args[0];
      this._requestUrl = args[1];
      return originalOpen.apply(this, args);
    };

    const originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function(body) {
      this.captureRequest('xhr', {
        method: this._requestMethod,
        url: this._requestUrl,
        body: body
      });
      return originalSend.apply(this, arguments);
    };
  }

  handleFormSubmit(event) {
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;

    const formData = this.extractFormData(form);
    this.captureFormData(formData, form.action || window.location.href);
  }

  extractFormData(form) {
    const formData = new FormData(form);
    const data = {};

    for (const [key, value] of formData.entries()) {
      if (!data[key]) {
        data[key] = value;
      } else {
        if (!Array.isArray(data[key])) {
          data[key] = [data[key]];
        }
        data[key].push(value);
      }
    }

    return data;
  }

  captureRequest(type, requestData) {
    // Filter sensitive fields
    const filtered = this.filterSensitiveData(requestData);

    const capture = {
      timestamp: new Date().toISOString(),
      type: type,
      domain: window.location.hostname,
      url: window.location.href,
      data: filtered
    };

    chrome.runtime.sendMessage({
      action: 'storeCapture',
      capture: capture
    }).catch(err => console.error('[QA Capture] Error:', err));
  }

  captureFormData(formData, action) {
    const filtered = this.filterSensitiveData(formData);

    const capture = {
      timestamp: new Date().toISOString(),
      type: 'form_submission',
      domain: window.location.hostname,
      url: window.location.href,
      action: action,
      data: filtered
    };

    chrome.runtime.sendMessage({
      action: 'storeCapture',
      capture: capture
    }).catch(err => console.error('[QA Capture] Error:', err));
  }

  filterSensitiveData(data) {
    const sensitivePatterns = [
      /password/i,
      /pin/i,
      /cvv/i,
      /ssn/i,
      /credit.?card/i,
      /token/i,
      /secret/i,
      /api.?key/i
    ];

    const filtered = { ...data };

    Object.keys(filtered).forEach(key => {
      const isSensitive = sensitivePatterns.some(pattern => 
        pattern.test(key)
      );

      if (isSensitive) {
        filtered[key] = '[REDACTED]';
      }
    });

    return filtered;
  }
}

