/**
 * Background service worker - Manages storage and syncing
 */

class CaptureManager {
  constructor() {
    this.syncInterval = null;
    this.maxLocalCaptures = 1000;
    this.init();
  }

  async init() {
    const settings = await chrome.storage.local.get([
      'syncEndpoint',
      'syncInterval',
      'certificatePinning',
      'enabledDomains'
    ]);

    if (settings.syncEndpoint) {
      this.startSync(settings.syncInterval || 300000); // 5 min default
    }

    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'storeCapture') {
        this.storeCapture(request.capture);
      }
    });
  }

  async storeCapture(capture) {
    try {
      const { captures = [] } = await chrome.storage.local.get('captures');

      // Add metadata
      capture.id = Date.now() + Math.random();
      capture.synced = false;

      captures.push(capture);

      // Maintain size limit
      if (captures.length > this.maxLocalCaptures) {
        captures.shift();
      }

      await chrome.storage.local.set({ captures });
      console.log('[QA Capture] Stored:', capture.id);
    } catch (error) {
      console.error('[QA Capture] Storage error:', error);
    }
  }

  startSync(interval) {
    this.syncInterval = setInterval(() => this.sync(), interval);
    this.sync(); // Sync immediately
  }

  async sync() {
    const settings = await chrome.storage.local.get([
      'syncEndpoint',
      'certificatePinning'
    ]);

    if (!settings.syncEndpoint) return;

    const { captures = [] } = await chrome.storage.local.get('captures');
    const toSync = captures.filter(c => !c.synced);

    if (toSync.length === 0) return;

    try {
      const payload = {
        timestamp: new Date().toISOString(),
        captures: toSync
      };

      const options = {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'User-Agent': 'QA-Form-Capture/1.0'
        },
        body: JSON.stringify(payload)
      };

      // Certificate pinning via custom validation
      if (settings.certificatePinning) {
        options.headers['X-Cert-Pin'] = settings.certificatePinning;
      }

      const response = await fetch(settings.syncEndpoint, options);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      // Mark as synced
      const updated = captures.map(c => 
        toSync.find(ts => ts.id === c.id) 
          ? { ...c, synced: true, syncedAt: new Date().toISOString() }
          : c
      );

      await chrome.storage.local.set({ captures: updated });
      console.log('[QA Capture] Synced:', toSync.length, 'captures');

    } catch (error) {
      console.error('[QA Capture] Sync failed:', error);
    }
  }

  stopSync() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
      this.syncInterval = null;
    }
  }
}

