```javascript
/**
 * Content Script - Intercepts form submissions
 */

class FormInterceptor {
  constructor() {
    this.interceptedForms = [];
    this.init();
  }

  init() {
    // Listen for form submissions
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);

    // Monitor for dynamically added forms
    this.observeDOMChanges();

    // Listen for messages from popup/background
    chrome.runtime.onMessage.addListener(
      (request, sender, sendResponse) => this.handleMessage(request, sendResponse)
    );
  }

  handleFormSubmit(event) {
    const form = event.target;

    // Create form data snapshot
    const formData = this.extractFormData(form);

    // Store in IndexedDB
    this.storeFormData(formData);

    // Send to background script for sync
    chrome.runtime.sendMessage({
      action: 'formIntercepted',
      data: formData
    });

    console.log('[QA Interceptor] Form captured:', formData);
  }

  extractFormData(form) {
    const formData = new FormData(form);
    const data = {
      timestamp: new Date().toISOString(),
      url: window.location.href,
      formId: form.id || 'unnamed-form',
      formName: form.name || '',
      action: form.action || '',
      method: form.method || 'GET',
      fields: {}
    };

    // Extract all form fields
    for (let [key, value] of formData.entries()) {
      if (!data.fields[key]) {
        data.fields[key] = [];
      }
      data.fields[key].push(value);
    }

    // Convert arrays with single values to strings
    Object.keys(data.fields).forEach(key => {
      if (data.fields[key].length === 1) {
        data.fields[key] = data.fields[key][0];
      }
    });

    // Add computed values
    data.fieldCount = Object.keys(data.fields).length;
    data.id = this.generateId();

    return data;
  }

  storeFormData(data) {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('QAFormInterceptor', 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = (event) => {
        const db = event.target.result;
        const transaction = db.transaction(['forms'], 'readwrite');
        const store = transaction.objectStore('forms');

        store.add(data);
        transaction.oncomplete = () => resolve(data);
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('forms')) {
          const store = db.createObjectStore('forms', { keyPath: 'id' });
          store.createIndex('timestamp', 'timestamp', { unique: false });
          store.createIndex('url', 'url', { unique: false });
          store.createIndex('synced', 'synced', { unique: false });
        }
      };
    });
  }

  observeDOMChanges() {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach((node) => {
            if (node.nodeType === 1) { // Element node
              if (node.tagName === 'FORM') {
                this.attachFormListener(node);
              }
              node.querySelectorAll?.('form').forEach(
                (form) => this.attachFormListener(form)
              );
            }
          });
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  attachFormListener(form) {
    if (!form.hasAttribute('data-qa-intercepted')) {
      form.addEventListener('submit', (e) => this.handleFormSubmit(e), true);
      form.setAttribute('data-qa-intercepted', 'true');
    }
  }

  handleMessage(request, sendResponse) {
    if (request.action === 'getLocalForms') {
      this.getLocalForms().then(sendResponse);
      return true;
    }
    if (request.action === 'clearLocalForms') {
      this.clearLocalForms().then(() => sendResponse({ success: true }));
      return true;
    }
  }

  getLocalForms() {
    return new Promise((resolve) => {
      const request = indexedDB.open('QAFormInterceptor', 1);
      request.onsuccess = (event) => {
        const db = event.target.result;
        const transaction = db.transaction(['forms'], 'readonly');
        const store = transaction.objectStore('forms');
        const getAllRequest = store.getAll();

        getAllRequest.onsuccess = () => {
          resolve(getAllRequest.result);
        };
      };
    });
  }

  clearLocalForms() {
    return new Promise((resolve) => {
      const request = indexedDB.open('QAFormInterceptor', 1);
      request.onsuccess = (event) => {
        const db = event.target.result;
        const transaction = db.transaction(['forms'], 'readwrite');
        const store = transaction.objectStore('forms');
        const clearRequest = store.clear();

        clearRequest.onsuccess = () => {
          resolve();
        };
      };
    });
  }

  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

