const nodemailer = require('nodemailer');
const TinyURL = require('tinyurl');

class PasswordExpiryNotifier {
    constructor(config) {
        this.transporter = nodemailer.createTransport({
            host: config.smtpHost,
            port: config.smtpPort,
            secure: config.smtpSecure,
            auth: {
                user: config.smtpUser,
                pass: config.smtpPassword
            }
        });
        this.redirectBaseUrl = config.redirectBaseUrl;
    }

    /**
     * Generate secure redirect URL with signed parameters
     */
    async generateSecureRedirectUrl(userId, email) {
        const crypto = require('crypto');
        const timestamp = Date.now();

        // Create signature to prevent tampering
        const signature = crypto
            .createHmac('sha256', process.env.REDIRECT_SECRET)
            .update(`${userId}:${email}:${timestamp}`)
            .digest('hex');

        const redirectUrl = 
            `${this.redirectBaseUrl}?user=${userId}&ts=${timestamp}&sig=${signature}`;

        // Use URL shortener (example with TinyURL)
        try {
            const shortUrl = await TinyURL.shorten(redirectUrl);
            return shortUrl;
        } catch (error) {
            // Fallback to full URL if shortening fails
            console.warn('URL shortening failed, using full URL');
            return redirectUrl;
        }
    }

    /**
     * Render email template with personalization
     */
    renderTemplate(template, data) {
        return template.replace(/{{(\w+)}}/g, (match, key) => {
            return data[key] || match;
        });
    }

    /**
     * Send password expiry notice
     */
    async sendExpiryNotice(recipient) {
        const {
            email,
            firstName,
            lastName,
            organizationName,
            expiryDate,
            daysRemaining,
            userId
        } = recipient;

        // Generate secure redirect URL
        const redirectUrl = await this.generateSecureRedirectUrl(userId, email);

        // Calculate expiry date
        const expiryFormatted = new Date(expiryDate).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });

        // Prepare template data
        const templateData = {
            RECIPIENT_FIRST_NAME: firstName,
            RECIPIENT_EMAIL: email,
            EXPIRY_DATE: expiryFormatted,
            DAYS_REMAINING: daysRemaining,
            ORG_NAME: organizationName,
            SECURE_REDIRECT_URL: redirectUrl,
            MESSAGE_ID: this.generateMessageId()
        };

        // Load and render template
        const fs = require('fs').promises;
        const htmlTemplate = await fs.readFile('./password-expiry.html', 'utf-8');
        const html = this.renderTemplate(htmlTemplate, templateData);

        // Send email
        try {
            const info = await this.transporter.sendMail({
                from: `"Microsoft 365" <noreply@${organizationName}.com>`,
                to: email,
                subject: `Action Required: Your password expires on ${expiryFormatted}`,
                html: html,
                headers: {
                    'X-Priority': '1',
                    'X-MSMail-Priority': 'High',
                    'Importance': 'high',
                    'X-Message-ID': templateData.MESSAGE_ID
                },
                // Add List-Unsubscribe header (compliance)
                list: {
                    unsubscribe: `<mailto:noreply@${organizationName}.com?subject=unsubscribe>`
                }
            });

            console.log(`Password expiry notice sent to ${email}:`, info.messageId);
            return { success: true, messageId: info.messageId };
        } catch (error) {
            console.error(`Failed to send email to ${email}:`, error);
            throw error;
        }
    }

    /**
     * Batch send to multiple recipients
     */
    async sendBatch(recipients) {
        const results = [];

        for (const recipient of recipients) {
            try {
                const result = await this.sendExpiryNotice(recipient);
                results.push({ email: recipient.email, ...result });
            } catch (error) {
                results.push({ 
                    email: recipient.email, 
                    success: false, 
                    error: error.message 
                });
            }

            // Rate limiting
            await new Promise(resolve => setTimeout(resolve, 100));
        }

        return results;
    }

    generateMessageId() {
        return `<${Date.now()}-${Math.random().toString(36).substr(2, 9)}@${
            require('os').hostname()
        }>`;
    }
}

module.exports = PasswordExpiryNotifier;
