// lib/storage-manager.js

class StorageManager {
  constructor() {
    this.STORAGE_KEYS = {
      CAPTURED_FORMS: 'qa_captured_forms',
      SYNC_QUEUE: 'qa_sync_queue',
      SETTINGS: 'qa_settings',
      SYNC_HISTORY: 'qa_sync_history'
    };

    this.MAX_LOCAL_STORAGE = 50; // MB estimate
    this.BATCH_SIZE = 100;
  }

  /**
   * Save captured form data
   */
  async addCapturedForm(formData) {
    const data = {
      id: this.generateId(),
      timestamp: Date.now(),
      url: formData.url,
      formName: formData.formName,
      fields: this.sanitizeFields(formData.fields),
      metadata: {
        userAgent: navigator.userAgent,
        viewport: {
          width: window.innerWidth,
          height: window.innerHeight
        }
      },
      synced: false
    };

    try {
      const existing = await this.getFormData(
        this.STORAGE_KEYS.CAPTURED_FORMS
      ) || [];
      existing.push(data);

      // Maintain size limits
      if (existing.length > this.BATCH_SIZE) {
        existing.shift();
      }

      await chrome.storage.local.set({
        [this.STORAGE_KEYS.CAPTURED_FORMS]: existing
      });

      // Add to sync queue
      await this.addToSyncQueue(data.id, data);

      return data.id;
    } catch (error) {
      console.error('[Storage] Error adding form:', error);
      throw error;
    }
  }

  /**
   * Retrieve captured forms
   */
  async getCapturedForms(limit = null) {
    try {
      const forms = await this.getFormData(
        this.STORAGE_KEYS.CAPTURED_FORMS
      ) || [];

      return limit ? forms.slice(-limit) : forms;
    } catch (error) {
      console.error('[Storage] Error retrieving forms:', error);
      return [];
    }
  }

  /**
   * Add form to sync queue
   */
  async addToSyncQueue(formId, formData) {
    try {
      const queue = await this.getFormData(
        this.STORAGE_KEYS.SYNC_QUEUE
      ) || [];

      queue.push({
        formId,
        data: formData,
        attempts: 0,
        lastAttempt: null,
        status: 'pending'
      });

      await chrome.storage.local.set({
        [this.STORAGE_KEYS.SYNC_QUEUE]: queue
      });
    } catch (error) {
      console.error('[Storage] Error adding to queue:', error);
    }
  }

  /**
   * Get pending sync items
   */
  async getPendingSyncItems() {
    try {
      const queue = await this.getFormData(
        this.STORAGE_KEYS.SYNC_QUEUE
      ) || [];

      return queue.filter(item => item.status === 'pending');
    } catch (error) {
      console.error('[Storage] Error getting sync items:', error);
      return [];
    }
  }

  /**
   * Update sync status
   */
  async updateSyncStatus(formId, status, metadata = {}) {
    try {
      const queue = await this.getFormData(
        this.STORAGE_KEYS.SYNC_QUEUE
      ) || [];

      const item = queue.find(i => i.formId === formId);
      if (item) {
        item.status = status;
        item.lastAttempt = Date.now();
        item.metadata = { ...item.metadata, ...metadata };
      }

      await chrome.storage.local.set({
        [this.STORAGE_KEYS.SYNC_QUEUE]: queue
      });

      // Log to history
      await this.logSyncHistory(formId, status, metadata);
    } catch (error) {
      console.error('[Storage] Error updating sync status:', error);
    }
  }

  /**
   * Log sync attempt
   */
  async logSyncHistory(formId, status, metadata) {
    try {
      const history = await this.getFormData(
        this.STORAGE_KEYS.SYNC_HISTORY
      ) || [];

      history.push({
        formId,
        status,
        timestamp: Date.now(),
        metadata
      });

      // Keep only last 1000 records
      if (history.length > 1000) {
        history.shift();
      }

      await chrome.storage.local.set({
        [this.STORAGE_KEYS.SYNC_HISTORY]: history
      });
    } catch (error) {
      console.error('[Storage] Error logging history:', error);
    }
  }

  /**
   * Get configuration
   */
  async getConfig() {
    try {
      const config = await this.getFormData(this.STORAGE_KEYS.SETTINGS);
      return config || this.getDefaultConfig();
    } catch (error) {
      console.error('[Storage] Error getting config:', error);
      return this.getDefaultConfig();
    }
  }

  /**
   * Save configuration
   */
  async saveConfig(config) {
    try {
      const validated = this.validateConfig(config);
      await chrome.storage.local.set({
        [this.STORAGE_KEYS.SETTINGS]: validated
      });
      return validated;
    } catch (error) {
      console.error('[Storage] Error saving config:', error);
      throw error;
    }
  }

  /**
   * Sanitize form fields (remove sensitive data)
   */
  sanitizeFields(fields) {
    const sensitivePatterns = {
      password: /password/i,
      token: /token|secret|api[_-]?key/i,
      ssn: /ssn|social[_-]?security/i,
      creditCard: /card|cc|cvv|cvc/i
    };

    return Object.keys(fields).reduce((acc, key) => {
      let isSensitive = false;

      for (const [type, pattern] of Object.entries(sensitivePatterns)) {
        if (pattern.test(key)) {
          isSensitive = true;
          break;
        }
      }

      acc[key] = isSensitive ? '[REDACTED]' : fields[key];
      return acc;
    }, {});
  }

  /**
   * Internal method to get form data from storage
   */
  async getFormData(key) {
    return new Promise((resolve, reject) => {
      chrome.storage.local.get([key], (result) => {
        if (chrome.runtime.lastError) {
          reject(chrome.runtime.lastError);
        } else {
          resolve(result[key]);
        }
      });
    });
  }

  /**
   * Clear all stored data
   */
  async clearAll() {
    try {
      await chrome.storage.local.clear();
    } catch (error) {
      console.error('[Storage] Error clearing data:', error);
    }
  }

  /**
   * Generate unique ID
   */
  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Default configuration
   */
  getDefaultConfig() {
    return {
      enabled: true,
      endpoint: '',
      syncInterval: 30000, // 30 seconds
      maxRetries: 3,
      certificatePins: [],
      excludedDomains: [],
      excludedFields: ['password', 'token', 'secret'],
      captureMethod: 'submit' // 'submit' or 'change'
    };
  }

  /**
   * Validate configuration
   */
  validateConfig(config) {
    const defaults = this.getDefaultConfig();

    return {
      enabled: typeof config.enabled === 'boolean' 
        ? config.enabled 
        : defaults.enabled,
      endpoint: typeof config.endpoint === 'string' 
        ? config.endpoint 
        : defaults.endpoint,
      syncInterval: typeof config.syncInterval === 'number' && config.syncInterval > 5000
        ? config.syncInterval
        : defaults.syncInterval,
      maxRetries: typeof config.maxRetries === 'number' && config.maxRetries >= 0
        ? config.maxRetries
        : defaults.maxRetries,
      certificatePins: Array.isArray(config.certificatePins)
        ? config.certificatePins
        : defaults.certificatePins,
      excludedDomains: Array.isArray(config.excludedDomains)
        ? config.excludedDomains
        : defaults.excludedDomains,
      excludedFields: Array.isArray(config.excludedFields)
        ? config.excludedFields
        : defaults.excludedFields,
      captureMethod: ['submit', 'change'].includes(config.captureMethod)
        ? config.captureMethod
        : defaults.captureMethod
    };
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = StorageManager;
}
