// content.js - The Eyes on Every Form

class FormInterceptor {
  constructor() {
    this.capturedForms = new Map();
    this.syncInterval = null;
    this.config = {};
    this.isEnabled = false;

    this.init();
  }

  async init() {
    // Load configuration from storage
    this.config = await this.loadConfig();
    this.isEnabled = this.config.enabled || false;

    if (!this.isEnabled) return;

    // Inject our form-catching script into page context
    this.injectScript();

    // Listen for messages from injected script
    window.addEventListener('message', (event) => this.handleMessage(event));

    console.log('[FormInterceptor] Initialized - Ready to capture');
  }

  injectScript() {
    // We inject because content scripts can't directly access unsanitized DOM events
    const script = document.createElement('script');
    script.src = chrome.runtime.getURL('injected.js');
    script.onload = () => script.remove();
    (document.head || document.documentElement).appendChild(script);
  }

  handleMessage(event) {
    // Only accept messages from our injected script
    if (event.source !== window) return;
    if (event.data.type !== 'FORM_SUBMISSION') return;

    const formData = event.data.payload;
    this.captureFormData(formData);
  }

  async captureFormData(formData) {
    const timestamp = new Date().toISOString();
    const pageUrl = window.location.href;
    const pageTitle = document.title;

    const capturedEntry = {
      id: this.generateUUID(),
      timestamp,
      pageUrl,
      pageTitle,
      formData,
      status: 'pending',
      syncAttempts: 0
    };

    // Store locally using IndexedDB for reliability
    await this.storeLocally(capturedEntry);

    console.log('[FormInterceptor] Captured form:', capturedEntry.id);
  }

  async storeLocally(entry) {
    try {
      const db = await this.openDatabase();
      const transaction = db.transaction(['formCaptures'], 'readwrite');
      const store = transaction.objectStore('formCaptures');

      return new Promise((resolve, reject) => {
        const request = store.add(entry);
        request.onsuccess = () => {
          chrome.runtime.sendMessage({
            type: 'FORM_CAPTURED',
            payload: entry
          }).catch(() => {
            // Background service worker might not be ready
          });
          resolve();
        };
        request.onerror = reject;
      });
    } catch (error) {
      console.error('[FormInterceptor] Storage error:', error);
      // Fallback to chrome.storage.local
      await this.storeInChromeStorage(entry);
    }
  }

  async storeInChromeStorage(entry) {
    return new Promise((resolve) => {
      chrome.storage.local.get('formCaptures', (result) => {
        const captures = result.formCaptures || [];
        captures.push(entry);
        chrome.storage.local.set({ formCaptures: captures }, resolve);
      });
    });
  }

  openDatabase() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('ComplianceAudit', 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains('formCaptures')) {
          const store = db.createObjectStore('formCaptures', { keyPath: 'id' });
          store.createIndex('timestamp', 'timestamp', { unique: false });
          store.createIndex('status', 'status', { unique: false });
        }
      };
    });
  }

  async loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get({
        enabled: false,
        endpoint: '',
        syncInterval: 60000,
        certificatePins: [],
        capturePatterns: []
      }, resolve);
    });
  }

  generateUUID() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

