// injected.js - Injected into page context to bypass sandbox

class PageLevelFormCapture {
  constructor() {
    this.capturedCount = 0;
    this.init();
  }

  init() {
    // Intercept all form submissions
    document.addEventListener('submit', (event) => {
      this.captureSubmission(event);
    }, true); // Use capture phase to catch before other listeners

    // Also handle fetch/XHR form submissions
    this.interceptFetch();
    this.interceptXHR();

    console.log('[PageCapture] Ready to intercept submissions');
  }

  captureSubmission(event) {
    const form = event.target;
    if (!form || form.tagName !== 'FORM') return;

    const formData = this.extractFormData(form);

    // Send to content script via message
    window.postMessage({
      type: 'FORM_SUBMISSION',
      payload: {
        method: form.method || 'GET',
        action: form.action,
        fields: formData,
        timestamp: new Date().toISOString()
      }
    }, '*');

    console.log('[PageCapture] Form submitted:', formData.fieldCount, 'fields');
  }

  extractFormData(form) {
    const fields = [];
    const fieldMap = new Map();

    // Extract all input fields
    const inputs = form.querySelectorAll('input, textarea, select');
    inputs.forEach(input => {
      const field = {
        name: input.name || input.id,
        type: input.type || 'text',
        value: this.sanitizeValue(input),
        placeholder: input.placeholder || '',
        required: input.required || false
      };

      // Track field names to avoid duplicates
      if (!fieldMap.has(field.name)) {
        fields.push(field);
        fieldMap.set(field.name, true);
      }
    });

    return {
      fields,
      fieldCount: fields.length,
      formId: form.id,
      formName: form.name
    };
  }

  sanitizeValue(input) {
    // Sensitive field detection
    const sensitiveTypes = ['password', 'ssn', 'credit-card', 'cvv'];
    const sensitiveNames = ['password', 'ssn', 'creditcard', 'cvv', 'pin', 'secret'];

    const isSensitive = 
      sensitiveTypes.includes((input.type || '').toLowerCase()) ||
      sensitiveNames.some(name => 
        (input.name || '').toLowerCase().includes(name)
      );

    if (isSensitive) {
      return '[REDACTED]';
    }

    return input.value || '';
  }

  interceptFetch() {
    const originalFetch = window.fetch;

    window.fetch = async (...args) => {
      const [resource, config] = args;

      // Check if this is a form submission via fetch
      if (config?.body && this.isFormData(config.body)) {
        this.captureFromBody(config.body, resource);
      }

      return originalFetch.apply(this, args);
    };
  }

  interceptXHR() {
    const originalXHR = window.XMLHttpRequest;

    window.XMLHttpRequest = function() {
      const xhr = new originalXHR();
      const originalSend = xhr.send;

      xhr.send = function(body) {
        if (body && this.isFormData(body)) {
          this.captureFromBody(body, xhr.responseURL);
        }
        return originalSend.apply(this, arguments);
      }.bind(this);

      return xhr;
    };

    window.XMLHttpRequest.prototype = originalXHR.prototype;
  }

  isFormData(data) {
    return data instanceof FormData || 
           typeof data === 'string' && data.includes('=');
  }

  captureFromBody(body, url) {
    const fields = [];

    if (body instanceof FormData) {
      for (let [key, value] of body.entries()) {
        fields.push({
          name: key,
          value: this.sanitizeValue({ name: key, value }),
          type: 'formdata'
        });
      }
    } else if (typeof body === 'string') {
      const params = new URLSearchParams(body);
      for (let [key, value] of params.entries()) {
        fields.push({
          name: key,
          value: this.sanitizeValue({ name: key, value }),
          type: 'urlencoded'
        });
      }
    }

    window.postMessage({
      type: 'FORM_SUBMISSION',
      payload: {
        method: 'POST',
        action: url,
        fields,
        timestamp: new Date().toISOString()
      }
    }, '*');
  }
}

