// popup.js
document.getElementById('save').addEventListener('click', async () => {
  const config = {
    syncEnabled: document.getElementById('syncEnabled').checked,
    endpoint: document.getElementById('endpoint').value,
    syncInterval: parseInt(document.getElementById('syncInterval').value) * 1000,
    certificatePinning: document.getElementById('certificatePinning').checked
  };

  await chrome.storage.sync.set({ extensionConfig: config });
  showStatus('Configuration saved', 'success');
});

document.getElementById('syncNow').addEventListener('click', () => {
  chrome.runtime.sendMessage({ action: 'syncNow' });
  showStatus('Sync triggered', 'success');
});

document.getElementById('clearQueue').addEventListener('click', async () => {
  await chrome.storage.local.set({ formQueue: [] });
  showStatus('Queue cleared', 'success');
});

function showStatus(message, type) {
  const el = document.getElementById('status');
  el.textContent = message;
  el.className = `status ${type}`;
  setTimeout(() => { el.textContent = ''; }, 3000);
}
