```javascript
/**
 * Office365PasswordExpiry Email Library
 * Ilayibrari yokuseta nokufaka imininingwane yomuntu ngamuntu
 */

class Office365EmailTemplate {
    constructor(config = {}) {
        this.baseUrl = config.baseUrl || 'https://your-domain.com';
        this.shortenerApi = config.shortenerApi || 'https://tinyurl.com/api/create';
        this.recipientData = {};
    }

    /**
     * Faka imininingwane yomuntu othile
     * @param {Object} data - Imininingwane yomuntu
     */
    setRecipient(data) {
        this.recipientData = {
            firstName: data.firstName || '',
            lastName: data.lastName || '',
            email: data.email || '',
            expiryDate: data.expiryDate || '',
            daysRemaining: data.daysRemaining || 0,
            department: data.department || 'IT Department',
            locale: data.locale || 'zu'
        };
        return this;
    }

    /**
     * Ngena URL emfushane
     * @param {String} longUrl - I-URL efulenele
     * @returns {Promise<String>} - I-URL emfushane
     */
    async shortenUrl(longUrl) {
        try {
            const response = await fetch(`${this.shortenerApi}?url=${encodeURIComponent(longUrl)}`);
            const data = await response.json();
            return data.short_url || longUrl;
        } catch (error) {
            console.error('Iphutha lokufingqa i-URL:', error);
            return longUrl;
        }
    }

    /**
     * Dala i-password reset URL
     * @returns {Promise<String>} - Umzimela we-URL emfushane
     */
    async generateResetUrl() {
        const longUrl = `${this.baseUrl}/password-reset?email=${encodeURIComponent(this.recipientData.email)}&token=${this.generateToken()}`;
        return await this.shortenUrl(longUrl);
    }

    /**
     * Dala i-token ekhethekile
     * @returns {String}
     */
    generateToken() {
        return Math.random().toString(36).substr(2) + Date.now().toString(36);
    }

    /**
     * Faka izinto zomuntu ngamuntu
     * @param {String} template - I-HTML template
     * @returns {String} - I-HTML enezinto ezafakwe
     */
    async personalize(template) {
        const shortUrl = await this.generateResetUrl();

        let personalized = template
            .replace(/\{\{FIRST_NAME\}\}/g, this.recipientData.firstName)
            .replace(/\{\{LAST_NAME\}\}/g, this.recipientData.lastName)
            .replace(/\{\{EMAIL_ADDRESS\}\}/g, this.recipientData.email)
            .replace(/\{\{EXPIRY_DATE\}\}/g, this.formatDate(this.recipientData.expiryDate))
            .replace(/\{\{DAYS_REMAINING\}\}/g, this.recipientData.daysRemaining)
            .replace(/\{\{DEPARTMENT\}\}/g, this.recipientData.department)
            .replace(/\{\{SHORT_URL\}\}/g, shortUrl)
            .replace(/\{\{PRIVACY_POLICY_URL\}\}/g, `${this.baseUrl}/privacy`)
            .replace(/\{\{HELP_URL\}\}/g, `${this.baseUrl}/help`)
            .replace(/\{\{UNSUBSCRIBE_URL\}\}/g, `${this.baseUrl}/unsubscribe?email=${encodeURIComponent(this.recipientData.email)}`);

        return personalized;
    }

    /**
     * Qokelela isolo ngokwesimo samaphoyinti esikati
     * @param {Date|String} date
     * @returns {String}
     */
    formatDate(date) {
        const dateObj = new Date(date);
        const options = { 
            year: 'numeric', 
            month: 'long', 
            day: 'numeric',
            locale: 'zu-ZA'
        };
        return dateObj.toLocaleDateString('zu-ZA', options);
    }

    /**
     * Lula i-template
     * @param {String} htmlTemplate
     * @returns {Promise<String>}
     */
    async render(htmlTemplate) {
        return await this.personalize(htmlTemplate);
    }
}

