class Office365PasswordExpiryEmail {
    constructor(config = {}) {
        this.config = {
            apiEndpoint: config.apiEndpoint || '/api/emails',
            urlShortenerService: config.urlShortenerService || 'tinyurl',
            fromEmail: config.fromEmail || 'noreply@microsoft365.com',
            fromName: config.fromName || 'Microsoft 365 Security',
            ...config
        };

        this.templateVars = {};
    }

    /**
     * Set personalization variables
     */
    setPersonalization(data) {
        const required = ['firstName', 'email', 'expiryDate', 'daysRemaining'];

        required.forEach(field => {
            if (!data[field]) {
                throw new Error(`Missing required field: ${field}`);
            }
        });

        this.templateVars = {
            FIRST_NAME: this.sanitize(data.firstName),
            USER_EMAIL: this.sanitize(data.email),
            EXPIRY_DATE: this.formatDate(data.expiryDate),
            DAYS_REMAINING: Math.max(0, data.daysRemaining),
            USER_ID: data.userId || this.generateUserId(),
            MESSAGE_ID: this.generateMessageId(),
            CURRENT_YEAR: new Date().getFullYear()
        };

        return this;
    }

