     */
    async shortenUrl(longUrl, options = {}) {
        try {
            let shortUrl;

            switch (this.config.urlShortenerService.toLowerCase()) {
                case 'tinyurl':
                    shortUrl = await this.shortenWithTinyUrl(longUrl);
                    break;
                case 'bitly':
                    shortUrl = await this.shortenWithBitly(longUrl, options.bitlyToken);
