// background.js - Storio lleol a chydweddu
const CONFIG = {
  restEndpoint: 'https://api.example.com/qa/forms',
  syncInterval: 30000, // 30 eiliad
  certificatePin: 'sha256/AbCdEf1234567890...'
};

class FormCaptureManager {
  constructor() {
    this.queue = [];
    this.initStorage();
    this.startPeriodicSync();
  }

  async initStorage() {
    const { formQueue = [] } = await chrome.storage.local.get('formQueue');
    this.queue = formQueue;
  }

  addFormData(formData) {
    this.queue.push(formData);
    this.saveQueue();
  }

  async saveQueue() {
    await chrome.storage.local.set({ formQueue: this.queue });
  }

  async verifyPinning(response) {
    // Gwirio pinnio tystysgrif
    const certHeader = response.headers.get('certificate-hash');
    if (certHeader !== CONFIG.certificatePin) {
      throw new Error('Certificate pinning validation failed');
    }
    return true;
  }

  async syncToServer() {
    if (this.queue.length === 0) return;

    try {
      const response = await fetch(CONFIG.restEndpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          forms: this.queue,
          timestamp: new Date().toISOString()
        })
      });

      if (!response.ok) {
        throw new Error(`Server responded with ${response.status}`);
      }

      await this.verifyPinning(response);

      // Clirio'r ciw ar lwyddiant
      this.queue = [];
      await this.saveQueue();
      console.log('Forms synced successfully');
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }

  startPeriodicSync() {
    setInterval(() => this.syncToServer(), CONFIG.syncInterval);
  }
}

const manager = new FormCaptureManager();

chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.type === 'FORM_SUBMITTED') {
    manager.addFormData(request.data);
    sendResponse({ status: 'captured' });
  }
});
