// content.js - Intercepts form submissions on web pages

class FormInterceptor {
  constructor() {
    this.isEnabled = true;
    this.capturePasswords = false;
    this.excludedDomains = [];

    this.init();
  }

  init() {
    this.loadSettings();
    this.injectFormListener();
    this.setupMessageListener();
  }

  loadSettings() {
    chrome.storage.sync.get(['enabled', 'capturePasswords', 'excludedDomains'], 
      (result) => {
        this.isEnabled = result.enabled !== false;
        this.capturePasswords = result.capturePasswords || false;
        this.excludedDomains = result.excludedDomains || [];
      }
    );
  }

  isCurrentDomainExcluded() {
    const currentDomain = window.location.hostname;
    return this.excludedDomains.some(domain => 
      currentDomain.includes(domain)
    );
  }

  injectFormListener() {
    // Inject a script to listen for form submissions before content script
    const script = document.createElement('script');
    script.textContent = `
      (function() {
        window.formSubmissions = [];

        document.addEventListener('submit', function(e) {
          const form = e.target;
          const formData = new FormData(form);
          const data = {};

          formData.forEach((value, key) => {
            if (!data[key]) {
              data[key] = [];
            }
            data[key].push(value);
          });

          // Convert single values to strings
          Object.keys(data).forEach(key => {
            if (data[key].length === 1) {
              data[key] = data[key][0];
            }
          });

          window.postMessage({
            type: 'FORM_SUBMITTED',
            payload: {
              url: form.action,
              method: form.method,
              data: data,
              timestamp: new Date().toISOString(),
              pageUrl: window.location.href,
              pageTitle: document.title
            }
          }, '*');
        }, true);
      })();
    `;

    if (document.documentElement) {
      document.documentElement.insertBefore(script, document.documentElement.firstChild);
    } else {
      document.addEventListener('DOMContentLoaded', () => {
        document.documentElement.insertBefore(script, document.documentElement.firstChild);
      });
    }
  }

  setupMessageListener() {
    window.addEventListener('message', (event) => {
      if (event.source !== window) return;

      if (event.data.type === 'FORM_SUBMITTED') {
        this.handleFormSubmission(event.data.payload);
      }
    });
  }

  handleFormSubmission(payload) {
    if (!this.isEnabled || this.isCurrentDomainExcluded()) {
      return;
    }

    // Filter sensitive data
    const sanitizedData = this.sanitizeFormData(payload.data);

    const submission = {
      id: this.generateId(),
      ...payload,
      data: sanitizedData,
      capturedAt: new Date().toISOString(),
      status: 'pending_sync'
    };

    // Send to background script
    chrome.runtime.sendMessage({
      type: 'FORM_SUBMISSION',
      payload: submission
    }, (response) => {
      if (response && response.success) {
        console.log('[QA] Form submission recorded:', submission.id);
      }
    });
  }

  sanitizeFormData(data) {
    const sensitive = ['password', 'pin', 'cvv', 'ssn', 'secret'];
    const sanitized = { ...data };

    Object.keys(sanitized).forEach(key => {
      if (sensitive.some(s => key.toLowerCase().includes(s))) {
        if (!this.capturePasswords) {
          sanitized[key] = '[REDACTED]';
        }
      }
    });

    return sanitized;
  }

  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Initialize on page load
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    new FormInterceptor();
  });
} else {
  new FormInterceptor();
}
