/**
 * Certificate Pinning Implementation
 * Validates SSL certificates against pinned public keys
 */

class CertificatePinner {
  constructor() {
    this.pinnedCertificates = new Map();
    this.cacheExpiry = 24 * 60 * 60 * 1000; // 24 hours
  }

  /**
   * Add a certificate pin for a domain
   * @param {string} domain - Domain name
   * @param {string[]} publicKeyHashes - Array of SHA-256 hashes of public keys
   */
  addPin(domain, publicKeyHashes) {
    this.pinnedCertificates.set(domain, {
      hashes: publicKeyHashes,
      addedAt: Date.now()
    });
    chrome.storage.local.set({
      pinnedCertificates: Object.fromEntries(this.pinnedCertificates)
    });
  }

  /**
   * Verify certificate for a given URL
   * @param {string} url - URL to verify
   * @param {ArrayBuffer} certificateData - DER-encoded certificate
   * @returns {Promise<boolean>}
   */
  async verifyCertificate(url, certificateData) {
    try {
      const urlObj = new URL(url);
      const domain = urlObj.hostname;

      // Check if we have a pin for this domain
      if (!this.pinnedCertificates.has(domain)) {
        console.warn(`No certificate pin found for domain: ${domain}`);
        return false;
      }

      const pinData = this.pinnedCertificates.get(domain);
      const publicKeyHash = await this.extractPublicKeyHash(certificateData);

      return pinData.hashes.includes(publicKeyHash);
    } catch (error) {
      console.error('Certificate verification error:', error);
      return false;
    }
  }

  /**
   * Extract public key hash from certificate
   * @param {ArrayBuffer} certificateData - DER-encoded certificate
   * @returns {Promise<string>} SHA-256 hash of public key in base64
   */
  async extractPublicKeyHash(certificateData) {
    try {
      // Parse DER certificate
      const cert = this.parseDERCertificate(certificateData);

      // Extract public key
      const publicKey = cert.publicKey;

      // Create SHA-256 hash of public key
      const hashBuffer = await crypto.subtle.digest('SHA-256', publicKey);

      // Convert to base64
      return this.bufferToBase64(hashBuffer);
    } catch (error) {
      console.error('Error extracting public key hash:', error);
      throw error;
    }
  }

  /**
   * Parse DER-encoded certificate
   * This is a simplified parser. For production, use a proper ASN.1 library
   * @param {ArrayBuffer} derData
   * @returns {Object} Parsed certificate data
   */
  parseDERCertificate(derData) {
    // For production use, implement proper ASN.1 parsing
    // or use a library like asn1.js or node-asn1
    return {
      publicKey: derData
    };
  }

  /**
   * Convert ArrayBuffer to base64 string
   * @param {ArrayBuffer} buffer
   * @returns {string}
   */
  bufferToBase64(buffer) {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  /**
   * Load pinned certificates from storage
   * @returns {Promise<void>}
   */
  async loadFromStorage() {
    return new Promise((resolve) => {
      chrome.storage.local.get(['pinnedCertificates'], (result) => {
        if (result.pinnedCertificates) {
          this.pinnedCertificates = new Map(
            Object.entries(result.pinnedCertificates)
          );
        }
        resolve();
      });
    });
  }
}

