/**
 * Content script to intercept form submissions
 */

class FormInterceptor {
  constructor() {
    this.isEnabled = true;
    this.sensitiveFields = [
      'password',
      'pin',
      'cvv',
      'credit_card',
      'ssn',
      'token'
    ];
    this.init();
  }

  init() {
    this.checkExtensionStatus();
    this.interceptForms();
    this.setupMessageListener();
  }

  checkExtensionStatus() {
    chrome.storage.local.get(['extensionEnabled'], (result) => {
      this.isEnabled = result.extensionEnabled !== false;
    });
  }

  setupMessageListener() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'toggleExtension') {
        this.isEnabled = request.enabled;
        sendResponse({ success: true });
      }
    });
  }

  interceptForms() {
    // Intercept form submissions
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);

    // Intercept fetch requests
    const originalFetch = window.fetch;
    window.fetch = (...args) => {
      this.interceptFetchRequest(args);
      return originalFetch.apply(this, args);
    };

    // Intercept XMLHttpRequest
    const originalOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function(method, url, ...rest) {
      this._interceptionData = { method, url };
      return originalOpen.apply(this, [method, url, ...rest]);
    };

    const originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function(body) {
      if (this._interceptionData) {
        this._interceptionData.body = body;
      }
      return originalSend.apply(this, arguments);
    };
  }

  handleFormSubmit(e) {
    if (!this.isEnabled) return;

    const form = e.target;
    if (!(form instanceof HTMLFormElement)) return;

    const formData = this.extractFormData(form);

    // Send to background script for storage
    chrome.runtime.sendMessage({
      action: 'storeFormSubmission',
      data: {
        formData,
        url: window.location.href,
        method: form.method || 'GET',
        action: form.action || window.location.pathname,
        timestamp: new Date().toISOString()
      }
    }, (response) => {
      if (response && response.success) {
        this.showNotification('Form captured for testing');
      }
    });
  }

  extractFormData(form) {
    const data = new FormData(form);
    const extracted = {};

    for (const [key, value] of data.entries()) {
      if (this.isSensitiveField(key)) {
        extracted[key] = '[REDACTED]';
      } else {
        extracted[key] = value;
      }
    }

    return extracted;
  }

  isSensitiveField(fieldName) {
    const lowerName = fieldName.toLowerCase();
    return this.sensitiveFields.some(field => 
      lowerName.includes(field)
    );
  }

  interceptFetchRequest(args) {
    if (!this.isEnabled) return;

    const [url, options = {}] = args;

    // Only intercept POST/PUT/PATCH requests with form data
    if (!['POST', 'PUT', 'PATCH'].includes((options.method || 'GET').toUpperCase())) {
      return;
    }

    try {
      const body = this.parseRequestBody(options.body);
      if (body && Object.keys(body).length > 0) {
        chrome.runtime.sendMessage({
          action: 'storeFetchInterception',
          data: {
            url: url.toString(),
            method: options.method || 'POST',
            body: this.sanitizeData(body),
            timestamp: new Date().toISOString()
          }
        });
      }
    } catch (error) {
      console.warn('Failed to intercept fetch:', error);
    }
  }

  parseRequestBody(body) {
    if (!body) return null;

    try {
      if (typeof body === 'string') {
        // Try JSON
        try {
          return JSON.parse(body);
        } catch {
          // Try URLSearchParams
          const params = new URLSearchParams(body);
          const obj = {};
          for (const [key, value] of params.entries()) {
            obj[key] = value;
          }
          return obj;
        }
      } else if (body instanceof FormData) {
        const obj = {};
        for (const [key, value] of body.entries()) {
          obj[key] = value;
        }
        return obj;
      }
    } catch (error) {
      console.warn('Failed to parse request body:', error);
    }
    return null;
  }

  sanitizeData(data) {
    const sanitized = { ...data };
    for (const key in sanitized) {
      if (this.isSensitiveField(key)) {
        sanitized[key] = '[REDACTED]';
      }
    }
    return sanitized;
  }

  showNotification(message) {
    const notification = document.createElement('div');
    notification.textContent = message;
    notification.style.cssText = `
      position: fixed;
      top: 20px;
      right: 20px;
      background: #4CAF50;
      color: white;
      padding: 16px;
      border-radius: 4px;
      z-index: 10000;
      font-family: Arial, sans-serif;
      font-size: 14px;
      box-shadow: 0 2px 5px rgba(0,0,0,0.2);
    `;
    document.body.appendChild(notification);
    setTimeout(() => notification.remove(), 3000);
  }
}

