/**
 * Background service worker for storage and syncing
 */

const DB_NAME = 'FormInterceptorDB';
const STORE_NAME = 'formSubmissions';
const CONFIG_STORE = 'config';
const SYNC_INTERVAL = 60000; // 1 minute

class FormInterceptorBackend {
  constructor() {
    this.syncTimer = null;
    this.certificatePins = {};
    this.init();
  }

  init() {
    this.initializeStorage();
    this.setupMessageListeners();
    this.loadConfiguration();
    this.startPeriodicSync();
  }

  initializeStorage() {
    return new Promise((resolve) => {
      const request = indexedDB.open(DB_NAME, 1);

      request.onerror = () => {
        console.error('IndexedDB initialization failed');
        resolve(false);
      };

      request.onsuccess = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          const objectStore = db.createObjectStore(STORE_NAME, 
            { keyPath: 'id', autoIncrement: true }
          );
          objectStore.createIndex('timestamp', 'timestamp', { unique: false });
          objectStore.createIndex('synced', 'synced', { unique: false });
        }
        if (!db.objectStoreNames.contains(CONFIG_STORE)) {
          db.createObjectStore(CONFIG_STORE, { keyPath: 'key' });
        }
        resolve(true);
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          const objectStore = db.createObjectStore(STORE_NAME,
            { keyPath: 'id', autoIncrement: true }
          );
          objectStore.createIndex('timestamp', 'timestamp', { unique: false });
          objectStore.createIndex('synced', 'synced', { unique: false });
        }
        if (!db.objectStoreNames.contains(CONFIG_STORE)) {
          db.createObjectStore(CONFIG_STORE, { keyPath: 'key' });
        }
      };
    });
  }

  setupMessageListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      switch (request.action) {
        case 'storeFormSubmission':
          this.storeFormSubmission(request.data)
            .then(() => sendResponse({ success: true }))
            .catch(err => sendResponse({ success: false, error: err.message }));
          return true;

        case 'storeFetchInterception':
          this.storeFetchInterception(request.data)
            .then(() => sendResponse({ success: true }))
            .catch(err => sendResponse({ success: false, error: err.message }));
          return true;

        case 'getStoredSubmissions':
          this.getStoredSubmissions()
            .then(data => sendResponse({ success: true, data }))
            .catch(err => sendResponse({ success: false, error: err.message }));
          return true;

        case 'clearStoredData':
          this.clearStoredData()
            .then(() => sendResponse({ success: true }))
            .catch(err => sendResponse({ success: false, error: err.message }));
          return true;

        case 'syncNow':
          this.performSync()
            .then(result => sendResponse({ success: true, result }))
