// src/content.js
class FormInterceptor {
  constructor() {
    this.forms = new Map();
    this.init();
  }

  init() {
    this.interceptForms();
    this.observeNewForms();
  }

  interceptForms() {
    document.querySelectorAll('form').forEach((form, index) => {
      this.attachFormListener(form, index);
    });
  }

  observeNewForms() {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.nodeType === 1) {
            if (node.tagName === 'FORM') {
              this.attachFormListener(node, this.forms.size);
            }
            node.querySelectorAll?.('form').forEach((form, index) => {
              if (!this.forms.has(form)) {
                this.attachFormListener(form, this.forms.size + index);
              }
            });
          }
        });
      });
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  }

  attachFormListener(form, index) {
    if (this.forms.has(form)) return;

    const formId = `form_${index}_${Date.now()}`;
    this.forms.set(form, formId);

    form.addEventListener('submit', (e) => this.handleFormSubmit(e, formId));
  }

  handleFormSubmit(event, formId) {
    const formData = this.extractFormData(event.target);
    const payload = {
      id: formId,
      timestamp: new Date().toISOString(),
      url: window.location.href,
      title: document.title,
      fields: formData,
      userAgent: navigator.userAgent
    };

    chrome.runtime.sendMessage({
      action: 'captureForm',
      payload
    }, (response) => {
      if (response?.success) {
        console.log('[QA Interceptor] Form captured:', formId);
      }
    });
  }

  extractFormData(form) {
    const formData = new FormData(form);
    const data = {};

    for (const [key, value] of formData.entries()) {
      if (!data[key]) {
        data[key] = value;
      } else if (Array.isArray(data[key])) {
        data[key].push(value);
      } else {
        data[key] = [data[key], value];
      }
    }

    return data;
  }
}

