// Certificate pinning implementation
class CertificatePinning {
  constructor() {
    this.pins = new Map();
    this.publicKeyCache = new Map();
  }

  async extractPublicKeyFromCertificate(certificateChain) {
    // Extract SPKI (Subject Public Key Info) from certificate
    // This is a simplified version - production should use proper crypto libraries
    try {
      const cert = certificateChain[0];
      const publicKeyDer = await this.getPublicKeyDER(cert);
      return this.calculateSHA256Pin(publicKeyDER);
    } catch (error) {
      console.error('Error extracting public key:', error);
      return null;
    }
  }

  calculateSHA256Pin(publicKeyDer) {
    // Calculate pin-sha256 format
    return new Promise((resolve) => {
      const hashBuffer = crypto.subtle.digest('SHA-256', publicKeyDer);
      hashBuffer.then(buffer => {
        const hashArray = Array.from(new Uint8Array(buffer));
        const hashBase64 = btoa(String.fromCharCode(...hashArray));
        resolve(`pin-sha256="${hashBase64}"`);
      });
    });
  }

  async verifyPin(hostname, certificatePins) {
    // Verify certificate pin against configured pins
    if (!certificatePins || certificatePins.length === 0) {
      return true; // Skip verification if no pins configured
    }

    try {
      const response = await fetch(`https://${hostname}`, {
        method: 'HEAD',
        mode: 'no-cors'
      });

      // In production, extract actual certificate from response
      // and verify against pins
      return this.pins.has(hostname);
    } catch (error) {
      console.error('Certificate verification error:', error);
      return false;
    }
  }

  async addPin(hostname, pin) {
    if (!this.pins.has(hostname)) {
      this.pins.set(hostname, []);
    }
    this.pins.get(hostname).push(pin);
  }

  getPins(hostname) {
    return this.pins.get(hostname) || [];
  }
}

