// Content script - runs in page context
class FormInterceptor {
  constructor() {
    this.capturedForms = [];
    this.init();
  }

  init() {
    this.interceptFormSubmissions();
    this.observeFormChanges();
  }

  interceptFormSubmissions() {
    document.addEventListener('submit', (event) => {
      this.captureFormData(event);
    }, true);

    // Fallback for AJAX form submissions
    this.interceptXHR();
    this.interceptFetch();
  }

  captureFormData(event) {
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;

    const formData = this.extractFormFields(form);
    const captureData = {
      timestamp: Date.now(),
      url: window.location.href,
      formId: form.id || form.name || 'unnamed',
      formAction: form.action,
      formMethod: form.method || 'GET',
      fields: formData
    };

    // Send to background script
    chrome.runtime.sendMessage({
      type: 'FORM_CAPTURED',
      data: captureData
    });

    console.log('Form captured:', captureData);
  }

  extractFormFields(form) {
    const fields = {};
    const formElements = form.querySelectorAll(
      'input, textarea, select, button'
    );

    formElements.forEach(element => {
      const name = element.name || element.id;
      if (!name) return;

      // Skip sensitive fields
      if (this.isSensitiveField(name, element)) return;

      const type = element.type || element.tagName.toLowerCase();

      if (element instanceof HTMLInputElement) {
        if (type === 'checkbox' || type === 'radio') {
          fields[name] = element.checked;
        } else if (type !== 'submit' && type !== 'reset') {
          fields[name] = element.value;
        }
      } else if (element instanceof HTMLTextAreaElement) {
        fields[name] = element.value;
      } else if (element instanceof HTMLSelectElement) {
        fields[name] = element.value;
      } else if (element instanceof HTMLButtonElement) {
        if (element.value) {
          fields[name] = element.value;
        }
      }
    });

    return fields;
  }

  isSensitiveField(name, element) {
    const sensitivePatterns = [
      'password', 'pin', 'cvv', 'ssn', 'credit',
      'card', 'token', 'secret', 'apikey', 'auth'
    ];

    const nameLower = name.toLowerCase();
    const typeLower = (element.type || '').toLowerCase();

    return sensitivePatterns.some(pattern =>
      nameLower.includes(pattern) || typeLower.includes(pattern)
    );
  }

  interceptXHR() {
    const originalXHR = window.XMLHttpRequest;
    const self = this;

    window.XMLHttpRequest = function() {
      const xhr = new originalXHR();
      const originalOpen = xhr.open;
      const originalSend = xhr.send;

      xhr.open = function(method, url, ...args) {
        xhr._method = method;
        xhr._url = url;
        return originalOpen.apply(xhr, [method, url, ...args]);
      };

      xhr.send = function(body) {
        if (body && typeof body === 'string') {
          try {
            const params = new URLSearchParams(body);
            const data = Object.fromEntries(params);
            const captureData = {
              timestamp: Date.now(),
              url: window.location.href,
              method: xhr._method,
              endpoint: xhr._url,
              fields: data,
              type: 'xhr'
            };
            chrome.runtime.sendMessage({
              type: 'FORM_CAPTURED',
              data: captureData
            });
          } catch (e) {
            // Silently fail for non-form data
          }
        }
        return originalSend.apply(xhr, arguments);
      };

      return xhr;
    };

    window.XMLHttpRequest.prototype = originalXHR.prototype;
  }

  interceptFetch() {
    const originalFetch = window.fetch;
    const self = this;

    window.fetch = function(...args) {
      const [resource, config] = args;
      const url = typeof resource === 'string' ? resource : resource.url;

      if (config?.body) {
        try {
          let body = config.body;
          if (typeof body === 'string') {
            const params = new URLSearchParams(body);
            const data = Object.fromEntries(params);

            const captureData = {
              timestamp: Date.now(),
              url: window.location.href,
              method: config.method || 'GET',
              endpoint: url,
              fields: data,
              type: 'fetch'
            };

            chrome.runtime.sendMessage({
              type: 'FORM_CAPTURED',
              data: captureData
            });
          }
        } catch (e) {
          // Silently fail
        }
      }

      return originalFetch.apply(window, args);
    };
  }

  observeFormChanges() {
    // Watch for dynamically added forms
    const observer = new MutationObserver(() => {
      this.interceptFormSubmissions();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true
    });
  }
}

// Initialize when DOM is ready
