```javascript
class Office365PasswordNotice {
    constructor(config = {}) {
        this.config = {
            shortenerApiUrl: config.shortenerApiUrl || 'https://tinyurl.com/api/create',
            resetUrl: config.resetUrl || 'https://account.activedirectory.windowsazure.com/ChangePassword.aspx',
            organizationName: config.organizationName || 'Your Organization',
            organizationAddress: config.organizationAddress || '',
            ...config
        };
    }

    async generateShortUrl(longUrl) {
        try {
            const response = await fetch(this.config.shortenerApiUrl, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: `url=${encodeURIComponent(longUrl)}`
            });
            const data = await response.json();
            return data.short_url || longUrl;
        } catch (error) {
            console.warn('URL shortening failed, using full URL', error);
            return longUrl;
        }
    }

    calculateDaysRemaining(expiryDate) {
        const expiry = new Date(expiryDate);
        const today = new Date();
        const diff = Math.ceil((expiry - today) / (1000 * 60 * 60 * 24));
        return Math.max(0, diff);
    }

    formatDate(date) {
        return new Date(date).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }

    async renderEmail(recipientData) {
        const {
            recipientName,
            recipientEmail,
            expiryDate,
            userId = ''
        } = recipientData;

        const daysRemaining = this.calculateDaysRemaining(expiryDate);
        const fullUrl = `${this.config.resetUrl}?user=${encodeURIComponent(userId || recipientEmail)}`;
        const shortUrl = await this.generateShortUrl(fullUrl);

        const emailHtml = this.getEmailTemplate();

        const placeholders = {
            '{{RECIPIENT_NAME}}': this.sanitize(recipientName),
            '{{RECIPIENT_EMAIL}}': this.sanitize(recipientEmail),
            '{{EXPIRY_DATE}}': this.formatDate(expiryDate),
            '{{DAYS_REMAINING}}': daysRemaining.toString(),
            '{{CURRENT_DATE}}': this.formatDate(new Date()),
            '{{SHORTENER_URL}}': shortUrl,
            '{{FULL_URL}}': fullUrl,
            '{{ORGANIZATION_NAME}}': this.sanitize(this.config.organizationName),
            '{{ORGANIZATION_ADDRESS}}': this.sanitize(this.config.organizationAddress)
        };

        let rendered = emailHtml;
        Object.entries(placeholders).forEach(([key, value]) => {
            rendered = rendered.replace(new RegExp(key, 'g'), value);
        });

        return rendered;
    }

    sanitize(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    getEmailTemplate() {
        // Returns the HTML template from above
        return document.querySelector('.email-container')?.outerHTML || '';
    }
}

