// Form interception in page context
class FormInterceptor {
  constructor() {
    this.interceptedForms = [];
    this.isEnabled = true;
    this.init();
  }

  init() {
    // Listen for enable/disable messages
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'toggleInterception') {
        this.isEnabled = request.enabled;
        sendResponse({ status: 'ok' });
      }
      if (request.action === 'getInterceptedForms') {
        sendResponse({ forms: this.interceptedForms });
      }
    });

    // Intercept form submissions
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);

    // Listen for dynamically added forms
    this.observeDOMChanges();
  }

  observeDOMChanges() {
    const observer = new MutationObserver(() => {
      document.querySelectorAll('form').forEach(form => {
        if (!form.hasAttribute('data-intercepted')) {
          this.attachFormListener(form);
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  attachFormListener(form) {
    form.setAttribute('data-intercepted', 'true');
    form.addEventListener('submit', (e) => this.handleFormSubmit(e), true);
  }

  handleFormSubmit(event) {
    if (!this.isEnabled) return;

    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;

    const formData = this.extractFormData(form);
    const interceptedForm = {
      id: this.generateId(),
      timestamp: new Date().toISOString(),
      url: window.location.href,
      method: form.method || 'GET',
      action: form.action || window.location.href,
      fields: formData,
      hostname: window.location.hostname
    };

    // Store locally
    chrome.runtime.sendMessage({
      action: 'storeFormData',
      data: interceptedForm
    }, (response) => {
      console.log('Form stored:', response);
    });

    this.interceptedForms.push(interceptedForm);
  }

  extractFormData(form) {
    const formData = new FormData(form);
    const fields = {};

    for (let [key, value] of formData.entries()) {
      if (!fields[key]) {
        fields[key] = [];
      }
      fields[key].push({
        value: this.sanitizeValue(value),
        type: this.getFieldType(form, key)
      });
    }

    return fields;
  }

  getFieldType(form, fieldName) {
    const field = form.querySelector(`[name="${fieldName}"]`);
    if (!field) return 'unknown';
    return field.type || field.tagName.toLowerCase();
  }

  sanitizeValue(value) {
    // Remove sensitive patterns
    if (typeof value !== 'string') return value;

    const sensitivePatterns = [
      /\b\d{16}\b/g, // Credit card
      /\b\d{3}-\d{2}-\d{4}\b/g, // SSN
      /password/i
    ];

    let sanitized = value;
    sensitivePatterns.forEach(pattern => {
      if (pattern.test(sanitized)) {
        sanitized = '[REDACTED]';
      }
    });
    return sanitized;
  }

  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

