class FormSyncManager {
  constructor() {
    this.config = {
      endpoint: 'https://api.example.com/qa/submissions',
      syncInterval: 30000, // 30 seconds
      batchSize: 50,
      certificatePin: null,
      apiKey: null
    };

    this.init();
  }

  async init() {
    await this.loadConfig();
    this.startPeriodicSync();
    this.setupListeners();
  }

  async loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get('config', (result) => {
        if (result.config) {
          this.config = { ...this.config, ...result.config };
        }
        resolve();
      });
    });
  }

  setupListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'FORM_SUBMITTED') {
        this.handleFormSubmission(request.data);
        sendResponse({ status: 'captured' });
      } else if (request.type === 'GET_CONFIG') {
        sendResponse(this.config);
      } else if (request.type === 'UPDATE_CONFIG') {
        this.updateConfig(request.config);
        sendResponse({ status: 'updated' });
      } else if (request.type === 'SYNC_NOW') {
        this.syncNow();
        sendResponse({ status: 'syncing' });
      }
    });
  }

  handleFormSubmission(data) {
    chrome.storage.local.get('pendingSync', (result) => {
      const pending = result.pendingSync || [];
      pending.push(data);
      chrome.storage.local.set({ pendingSync: pending });
    });
  }

  startPeriodicSync() {
    setInterval(() => this.syncNow(), this.config.syncInterval);
  }

  async syncNow() {
    try {
      await this.loadConfig();

      const { pendingSync } = await this.getStorageData('pendingSync');
      if (!pendingSync || pendingSync.length === 0) return;

      const batches = this.createBatches(pendingSync, this.config.batchSize);

      for (const batch of batches) {
        await this.sendBatch(batch);
      }

      chrome.storage.local.set({ pendingSync: [] });
      this.logSync('success', pendingSync.length);
    } catch (error) {
      this.logSync('error', error.message);
    }
  }

  async sendBatch(batch) {
    const payload = {
      submissions: batch,
      timestamp: new Date().toISOString(),
      extensionVersion: chrome.runtime.getManifest().version
    };

    const response = await this.fetchWithPinning(
      this.config.endpoint,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.config.apiKey}`,
          'X-Extension-ID': chrome.runtime.id
        },
        body: JSON.stringify(payload)
      }
    );

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json();
  }

  async fetchWithPinning(url, options) {
    const response = await fetch(url, options);

    if (this.config.certificatePin) {
      const certValid = await this.validateCertificatePin(url);
      if (!certValid) {
        throw new Error('Certificate pinning validation failed');
      }
    }

    return response;
  }

  async validateCertificatePin(url) {
    try {
      // Get the certificate from the response headers
      const response = await fetch(url, { method: 'HEAD' });

      // In a real scenario, you'd validate the certificate chain
      // This is a simplified implementation
      const secureConnection = url.startsWith('https://');

      if (!secureConnection && this.config.certificatePin) {
        return false;
      }

      // Store cert validation result
      return true;
    } catch (error) {
      console.error('Certificate validation error:', error);
      return false;
    }
  }

  createBatches(array, size) {
    const batches = [];
    for (let i = 0; i < array.length; i += size) {
      batches.push(array.slice(i, i + size));
    }
    return batches;
  }

  getStorageData(key) {
    return new Promise((resolve) => {
      chrome.storage.local.get(key, (result) => {
        resolve(result);
      });
    });
  }

  updateConfig(newConfig) {
    this.config = { ...this.config, ...newConfig };
    chrome.storage.sync.set({ config: this.config });
  }

  logSync(status, detail) {
    chrome.storage.local.get('syncLog', (result) => {
      const logs = result.syncLog || [];
      logs.push({
        timestamp: new Date().toISOString(),
        status,
        detail,
        pending: 0
      });

      // Keep last 100 logs
      if (logs.length > 100) {
        logs.shift();
      }

      chrome.storage.local.set({ syncLog: logs });
    });
  }
}

