/**
 * Configuration management with validation
 */

class Config {
  constructor() {
    this.defaults = {
      enabled: true,
      endpoint: '',
      syncInterval: 30000, // 30 seconds
      maxLocalStorage: 100, // max captures
      includePasswordFields: false,
      includeSensitivePatterns: false,
      certificatePinning: {
        enabled: false,
        pins: [] // Base64-encoded SPKI hashes
      },
      excludeSelectors: [
        'input[type="password"]',
        'input[data-qa-ignore]'
      ]
    };
  }

  /**
   * Load config from Chrome storage
   */
  async load() {
    return new Promise((resolve) => {
      chrome.storage.sync.get(this.defaults, (config) => {
        this.config = config;
        resolve(config);
      });
    });
  }

  /**
   * Save config to Chrome storage
   */
  async save(updates) {
    const validated = this.validate(updates);
    this.config = { ...this.config, ...validated };

    return new Promise((resolve, reject) => {
      chrome.storage.sync.set(validated, () => {
        if (chrome.runtime.lastError) {
          reject(chrome.runtime.lastError);
        } else {
          resolve(this.config);
        }
      });
    });
  }

  /**
   * Validate configuration
   */
  validate(config) {
    const validated = {};

    if ('endpoint' in config) {
      const url = new URL(config.endpoint);
      if (!['https:', 'http:'].includes(url.protocol)) {
        throw new Error('Endpoint must use HTTP or HTTPS');
      }
      validated.endpoint = config.endpoint;
    }

    if ('syncInterval' in config) {
      const interval = parseInt(config.syncInterval);
      if (interval < 5000 || interval > 300000) {
        throw new Error('Sync interval must be between 5s and 5m');
      }
      validated.syncInterval = interval;
    }

    if ('enabled' in config) {
      validated.enabled = Boolean(config.enabled);
    }

    if ('includePasswordFields' in config) {
      validated.includePasswordFields = Boolean(config.includePasswordFields);
    }

    if ('certificatePinning' in config) {
      validated.certificatePinning = this.validatePinning(
        config.certificatePinning
      );
    }

    return validated;
  }

  validatePinning(pinningConfig) {
    if (!pinningConfig.enabled) {
      return { enabled: false, pins: [] };
    }

    const pins = (pinningConfig.pins || []).filter((pin) => {
      // Validate Base64 SPKI hash format
      return /^[A-Za-z0-9+/]+=*$/.test(pin) && pin.length > 20;
    });

    return {
      enabled: true,
      pins
    };
  }

  get(key) {
    return this.config?.[key] ?? this.defaults[key];
  }
}

