// Local storage management
class StorageManager {
  constructor() {
    this.storageKey = 'capturedForms';
    this.maxSize = 5000000; // 5MB limit
  }

  async saveCapturedForm(formData) {
    return new Promise((resolve, reject) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        try {
          const forms = result[this.storageKey] || [];

          // Add metadata
          formData.id = this.generateId();
          formData.status = 'pending';
          formData.syncAttempts = 0;

          forms.push(formData);

          // Enforce size limit
          const serialized = JSON.stringify(forms);
          if (serialized.length > this.maxSize) {
            // Remove oldest entries
            forms.shift();
          }

          chrome.storage.local.set(
            { [this.storageKey]: forms },
            () => resolve(formData)
          );
        } catch (error) {
          reject(error);
        }
      });
    });
  }

  async getAllForms() {
    return new Promise((resolve) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        resolve(result[this.storageKey] || []);
      });
    });
  }

  async getPendingForms() {
    const forms = await this.getAllForms();
    return forms.filter(f => f.status === 'pending');
  }

  async updateFormStatus(formId, status, syncResponse = null) {
    return new Promise((resolve) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        const forms = result[this.storageKey] || [];
        const form = forms.find(f => f.id === formId);

        if (form) {
          form.status = status;
          form.lastSyncAttempt = new Date().toISOString();
          if (syncResponse) {
            form.syncResponse = syncResponse;
          }
          form.syncAttempts++;

          chrome.storage.local.set(
            { [this.storageKey]: forms },
            () => resolve(form)
          );
        } else {
          resolve(null);
        }
      });
    });
  }

  async clearForms(status = null) {
    return new Promise((resolve) => {
      if (!status) {
        chrome.storage.local.remove([this.storageKey], () => {
          resolve({ cleared: true });
        });
      } else {
        chrome.storage.local.get([this.storageKey], (result) => {
          const forms = (result[this.storageKey] || [])
            .filter(f => f.status !== status);

          chrome.storage.local.set(
            { [this.storageKey]: forms },
            () => resolve({ cleared: true })
          );
        });
      }
    });
  }

  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  async getStorageStats() {
    const forms = await this.getAllForms();
    const serialized = JSON.stringify(forms);

    return {
      totalForms: forms.length,
      pendingForms: forms.filter(f => f.status === 'pending').length,
      syncedForms: forms.filter(f => f.status === 'synced').length,
      failedForms: forms.filter(f => f.status === 'failed').length,
      storageSize: serialized.length,
      storageLimit: this.maxSize,
      percentUsed: (serialized.length / this.maxSize * 100).toFixed(2)
    };
  }
}

// Export for use in other scripts
if (typeof module !== 'undefined' && module.exports) {
  module.exports = StorageManager;
}
