async function saveFormData(data) {
  const { [STORAGE_KEY]: forms = [] } = await chrome.storage.local.get(STORAGE_KEY);
  forms.push(data);
  await chrome.storage.local.set({ [STORAGE_KEY]: forms });
}

function startPeriodicSync() {
  setInterval(syncForms, SYNC_INTERVAL);
}

async function syncForms() {
  const { [STORAGE_KEY]: forms = [], [CONFIG_KEY]: config } = 
    await chrome.storage.local.get([STORAGE_KEY, CONFIG_KEY]);

  if (!config.enabled || !forms.length) return;

  const unsyncedForms = forms.filter(f => !f.synced);
  if (!unsyncedForms.length) return;

  const batch = unsyncedForms.slice(0, config.batchSize);

  try {
    const response = await secureFetch(config.endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ forms: batch }),
      certificatePin: config.certificatePin
    });

    if (response.ok) {
      // Mark as synced
      const syncedIds = new Set(batch.map(f => f.id));
      const updated = forms.map(f => ({
        ...f,
        synced: syncedIds.has(f.id) ? true : f.synced
      }));
      await chrome.storage.local.set({ [STORAGE_KEY]: updated });

      console.log(`[QA] Synced ${batch.length} forms`);
    }
  } catch (error) {
    console.error('[QA] Sync failed:', error);
  }
}

