/**
 * Office 365 Password Expiry Email Library
 * Handles template rendering with personalization and URL shortening
 */

class Office365EmailTemplate {
    constructor(config = {}) {
        this.config = {
            shortenerService: config.shortenerService || 'tinyurl', // tinyurl, bitly, custom
            bitlyToken: config.bitlyToken || null,
            customShortenerEndpoint: config.customShortenerEndpoint || null,
            accountPortalUrl: config.accountPortalUrl || 'https://account.microsoft.com/account',
            helpPortalUrl: config.helpPortalUrl || 'https://support.microsoft.com',
            ...config
        };
    }

    /**
     * Generate password change URL
     */
    generatePasswordChangeUrl(userId, token) {
        const baseUrl = this.config.accountPortalUrl;
        const params = new URLSearchParams({
            user_id: userId,
            token: token,
            action: 'change-password',
            source: 'email_notification'
        });
        return `${baseUrl}?${params.toString()}`;
    }

    /**
     * Shorten URL using specified service
     */
    async shortenUrl(longUrl) {
        try {
            switch (this.config.shortenerService) {
                case 'bitly':
                    return await this.shortenWithBitly(longUrl);
                case 'tinyurl':
