class FormSyncManager {
  constructor() {
    this.config = null;
    this.syncInterval = null;
    this.certificatePins = {};
    this.init();
  }

  async init() {
    await this.loadConfig();
    this.setupSyncSchedule();
    this.setupMessageListeners();
  }

  async loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get(['endpoint', 'syncInterval', 'certificatePins'], (result) => {
        this.config = {
          endpoint: result.endpoint || 'https://qa-api.example.com/forms',
          syncInterval: result.syncInterval || 300000, // 5 minutes
          certificatePins: result.certificatePins || {}
        };
        this.certificatePins = this.config.certificatePins;
        resolve();
      });
    });
  }

  setupMessageListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'formIntercepted') {
        this.queueFormForSync(request.data);
        sendResponse({ success: true });
      }
      if (request.action === 'syncNow') {
        this.performSync().then(sendResponse);
        return true;
      }
      if (request.action === 'updateConfig') {
        this.updateConfig(request.config).then(() => {
          sendResponse({ success: true });
        });
        return true;
      }
    });
  }

  async queueFormForSync(formData) {
    try {
      const forms = await this.getLocalForms();
      forms.push({ ...formData, synced: false, queuedAt: new Date().toISOString() });

      await new Promise((resolve) => {
        chrome.storage.local.set({ queuedForms: forms }, resolve);
      });
    } catch (error) {
      console.error('[Sync Manager] Error queuing form:', error);
    }
  }

  async getLocalForms() {
    return new Promise((resolve) => {
      chrome.storage.local.get(['queuedForms'], (result) => {
        resolve(result.queuedForms || []);
      });
    });
  }

  setupSyncSchedule() {
    // Perform initial sync
    this.performSync();

    // Set up periodic sync
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }
    this.syncInterval = setInterval(
      () => this.performSync(),
      this.config.syncInterval
    );
  }

  async performSync() {
    try {
      const forms = await this.getLocalForms();
      const unsynced = forms.filter(f => !f.synced);

      if (unsynced.length === 0) {
        console.log('[Sync Manager] No unsynced forms');
        return { synced: 0, failed: 0 };
      }

      const results = await this.sendFormsToServer(unsynced);

      // Update sync status
      await this.updateSyncStatus(results);

      console.log(`[Sync Manager] Synced ${results.synced} forms, ${results.failed} failed`);
      return results;
    } catch (error) {
      console.error('[Sync Manager] Sync error:', error);
      return { synced: 0, failed: 0, error: error.message };
    }
  }

  async sendFormsToServer(forms) {
    const results = { synced: 0, failed: 0, errors: [] };

    for (const form of forms) {
      try {
        await this.fetchWithCertificatePinning(
          this.config.endpoint,
          {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-QA-Interceptor': '1.0.0'
            },
            body: JSON.stringify(form)
          }
        );
        results.synced++;
        form.synced = true;
        form.syncedAt = new Date().toISOString();
      } catch (error) {
        results.failed++;
        results.errors.push({ id: form.id, error: error.message });
        console.error(`[Sync Manager] Failed to sync form ${form.id}:`, error);
      }
    }

    return results;
  }

  async fetchWithCertificatePinning(url, options = {}) {
    const urlObj = new URL(url);
    const hostname = urlObj.hostname;

    // Fetch with timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal
      });

      // Verify certificate pinning (requires special handling)
      if (!await this.verifyCertificatePin(hostname, response)) {
        throw new Error('Certificate pin verification failed');
      }

      if (!response.ok) {
        throw new Error(`Server responded with ${response.status}`);
      }

      return await response.json();
    } finally {
      clearTimeout(timeoutId);
    }
  }

  async verifyCertificatePin(hostname, response) {
    // Note: Direct certificate pinning in content script is limited
    // This implements HPKP-style pinning via stored pins

    if (!this.certificatePins[hostname]) {
      console.warn(`[Certificate Pinning] No pin configured for ${hostname}`);
      return true; // Allow if not pinned
    }

    // In production, use a dedicated pinning library or server-side validation
    // For now, we implement basic header validation
    const certPin = response.headers.get('X-Certificate-Pin');

    if (certPin && certPin === this.certificatePins[hostname]) {
      return true;
    }

    console.error(`[Certificate Pinning] Pin mismatch for ${hostname}`);
    return false;
  }

  async updateSyncStatus(results) {
    const forms = await this.getLocalForms();
    const updated = forms.map(form => ({
      ...form,
      synced: form.synced === true
    }));

    return new Promise((resolve) => {
      chrome.storage.local.set({ queuedForms: updated }, resolve);
    });
  }

  async updateConfig(newConfig) {
    this.config = { ...this.config, ...newConfig };
    this.certificatePins = newConfig.certificatePins || this.certificatePins;

    return new Promise((resolve) => {
      chrome.storage.sync.set({
        endpoint: this.config.endpoint,
        syncInterval: this.config.syncInterval,
        certificatePins: this.certificatePins
      }, resolve);
    });
  }
}

