```javascript
// src/content-script.js

class FormInterceptor {
  constructor() {
    this.forms = new Map();
    this.config = null;
    this.init();
  }

  async init() {
    // Load configuration from extension storage
    this.config = await this.getConfig();
    this.setupFormListeners();
    this.setupMutationObserver();
  }

  getConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get({
        enabled: true,
        capturePasswords: false,
        excludeSelectors: 'input[type="password"]'
      }, resolve);
    });
  }

  setupFormListeners() {
    // Attach to existing forms
    document.querySelectorAll('form').forEach(form => {
      this.attachFormListener(form);
    });

    // Listen for dynamically added forms
    document.addEventListener('submit', (e) => {
      if (e.target.tagName === 'FORM') {
        this.interceptSubmit(e);
      }
    }, true); // Use capture phase
  }

  setupMutationObserver() {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        mutation.addedNodes.forEach((node) => {
          if (node.tagName === 'FORM') {
            this.attachFormListener(node);
          }
        });
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  attachFormListener(form) {
    const formId = this.generateFormId(form);
    form.addEventListener('submit', (e) => {
      this.interceptSubmit(e, formId);
    }, true);
  }

  interceptSubmit(event, formId) {
    if (!this.config.enabled) return;

    // Don't prevent default for now - just log
    // Production would decide based on QA mode

    const form = event.target;
    const formData = this.extractFormData(form);

    const submission = {
      id: this.generateSubmissionId(),
      timestamp: new Date().toISOString(),
      url: window.location.href,
      formId: formId || this.generateFormId(form),
      formName: form.name || form.id || 'unnamed',
      fields: formData,
      userAgent: navigator.userAgent,
      metadata: {
        formAction: form.action,
        formMethod: form.method,
        formEnctype: form.enctype,
        pageTitle: document.title
      }
    };

    // Send to background script for persistence
    chrome.runtime.sendMessage({
      type: 'FORM_SUBMITTED',
      payload: submission
    }, (response) => {
      console.log('Form logged:', response);
    });
  }

  extractFormData(form) {
    const fields = [];
    const excludeSelector = this.config.excludeSelectors || '';

    form.querySelectorAll('input, textarea, select').forEach((field) => {
      // Skip excluded fields
      if (excludeSelector && field.matches(excludeSelector)) {
        return;
      }

      // Skip if user disabled password capture
      if (field.type === 'password' && !this.config.capturePasswords) {
        return;
      }

      const fieldData = {
        name: field.name || field.id || 'unnamed',
        type: field.type || 'unknown',
        value: this.sanitizeValue(field),
        attributes: {
          id: field.id,
          class: field.className,
          required: field.required,
          readonly: field.readOnly,
          disabled: field.disabled
        }
      };

      fields.push(fieldData);
    });

    return fields;
  }

  sanitizeValue(field) {
    const type = field.type;

    if (type === 'checkbox' || type === 'radio') {
      return field.checked;
    }
    if (type === 'file') {
      return `[File: ${field.files?.length || 0} file(s)]`;
    }
    if (type === 'password') {
      return '[PASSWORD_REDACTED]';
    }

    return field.value || '';
  }

  generateFormId(form) {
    return form.id || `form_${form.getAttribute('data-form-id')}`;
  }

  generateSubmissionId() {
    return `submission_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

// Initialize when DOM is ready
if (document.readyState === 'loading') {
