## 4. Background Service Worker - Storage & Sync

```javascript
// src/background-script.js

class FormDataManager {
  constructor() {
    this.syncInterval = 60000; // 60 seconds
    this.maxRetries = 3;
    this.retryDelay = 5000;
    this.init();
  }

  async init() {
    this.config = await this.loadConfig();
    this.setupListeners();
    this.startPeriodicSync();
  }

  loadConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get({
        syncEnabled: true,
        syncInterval: 60000,
        endpoint: 'https://qa-api.example.com/submit',
        certificatePins: []
      }, resolve);
    });
  }

  setupListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'FORM_SUBMITTED') {
        this.handleFormSubmission(request.payload)
          .then(result => sendResponse({ success: true, ...result }))
          .catch(error => sendResponse({ success: false, error: error.message }));

        return true; // Keep channel open for async response
      }
    });

    // Listen for config changes
    chrome.storage.onChanged.addListener((changes) => {
      if (changes.syncInterval) {
        this.syncInterval = changes.syncInterval.newValue;
        this.restartPeriodicSync();
      }
    });
  }

  async handleFormSubmission(submission) {
    try {
      // Store locally first
      await this.storeLocally(submission);

      // Attempt immediate sync if sync is enabled
      if (this.config.syncEnabled) {
        return await this.syncSubmission(submission);
      }

      return { stored: true, synced: false };
    } catch (error) {
      console.error('Form submission handling error:', error);
      throw error;
    }
  }

  async storeLocally(submission) {
    return new Promise((resolve, reject) => {
      chrome.storage.local.get({ formSubmissions: [] }, (result) => {
        const submissions = result.formSubmissions || [];
        submissions.push(submission);

        // Keep only last 1000 submissions
        const trimmed = submissions.slice(-1000);

        chrome.storage.local.set(
          { formSubmissions: trimmed },
          () => {
            if (chrome.runtime.lastError) {
              reject(chrome.runtime.lastError);
            } else {
              resolve();
            }
          }
        );
      });
    });
  }

  async syncSubmission(submission, retryCount = 0) {
    try {
      const response = await this.sendToEndpoint(submission);

      if (response.ok) {
        await this.removeFromQueue(submission.id);
        return { synced: true, remoteId: response.id };
      }

      throw new Error(`Server returned ${response.status}`);
    } catch (error) {
      console.error('Sync error:', error);

      if (retryCount < this.maxRetries) {
        await this.delay(this.retryDelay);
        return this.syncSubmission(submission, retryCount + 1);
      }

      // Mark for retry
      await this.markForRetry(submission.id);
      throw error;
    }
  }

  async sendToEndpoint(submission) {
    const endpoint = this.config.endpoint;

    if (!endpoint) {
      throw new Error('Endpoint not configured');
    }

    // Prepare payload
    const payload = JSON.stringify(submission);

    // Build fetch options with certificate pinning
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Extension-Version': chrome.runtime.getManifest().version
      },
      body: payload
    };

    // Note: Certificate pinning in browser extensions is limited
    // This is theoretical - actual implementation depends on server support
    if (this.config.certificatePins && this.config.certificatePins.length > 0) {
      options.headers['X-Pinned-Keys'] = this.config.certificatePins.join(',');
    }

    const response = await fetch(endpoint, options);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    return await response.json();
  }

  async removeFromQueue(submissionId) {
    return new Promise((resolve) => {
      chrome.storage.local.get({ formSubmissions: [] }, (result) => {
        const submissions = (result.formSubmissions || []).filter(
          s => s.id !== submissionId
        );
        chrome.storage.local.set({ formSubmissions: submissions }, resolve);
      });
    });
  }

  async markForRetry(submissionId) {
    return new Promise((resolve) => {
      chrome.storage.local.get({ failedSubmissions: [] }, (result) => {
        const failed = result.failedSubmissions || [];
        if (!failed.includes(submissionId)) {
          failed.push(submissionId);
          chrome.storage.local.set({ failedSubmissions: failed }, resolve);
        } else {
          resolve();
        }
      });
    });
  }

  startPeriodicSync() {
    // Sync unsynced submissions
    this.periodicSyncTimer = setInterval(async () => {
      await this.syncPending();
    }, this.syncInterval);
  }

  restartPeriodicSync() {
    if (this.periodicSyncTimer) {
      clearInterval(this.periodicSyncTimer);
    }
    this.startPeriodicSync();
  }

  async syncPending() {
    if (!this.config.syncEnabled) return;

    return new Promise((resolve) => {
      chrome.storage.local.get({ formSubmissions: [] }, async (result) => {
        const submissions = result.formSubmissions || [];

        for (const submission of submissions) {
          try {
            await this.syncSubmission(submission);
          } catch (error) {
            console.error(`Failed to sync ${submission.id}:`, error);
          }
        }

        resolve();
      });
    });
  }

  delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

// Initialize the manager
new FormDataManager();
