```javascript
// content.js
class FormCapture {
  constructor() {
    this.config = {};
    this.queue = [];
    this.initListeners();
    this.loadConfig();
  }

  initListeners() {
    document.addEventListener('submit', (e) => this.captureForm(e), true);
  }

  async captureForm(event) {
    const form = event.target;
    const formData = new FormData(form);

    const capturedData = {
      timestamp: new Date().toISOString(),
      url: window.location.href,
      formId: form.id || form.name || 'unnamed',
      fields: this.extractFields(formData),
      userAgent: navigator.userAgent,
      sessionId: await this.getSessionId()
    };

    // Send to background script
    chrome.runtime.sendMessage({
      action: 'storeFormData',
      data: capturedData
    });

    console.log('[QA] Form captured:', capturedData.formId);
  }

  extractFields(formData) {
    const fields = {};
    for (const [key, value] of formData) {
      // Avoid capturing sensitive fields by default
      if (!this.isSensitiveField(key)) {
        fields[key] = value;
      }
    }
    return fields;
  }

  isSensitiveField(fieldName) {
    const sensitivePatterns = [
      /password/i,
      /credit.card/i,
      /cvv/i,
      /ssn/i,
      /secret/i
    ];
    return sensitivePatterns.some(p => p.test(fieldName));
  }

  async getSessionId() {
    const stored = await chrome.storage.local.get('sessionId');
    if (!stored.sessionId) {
      const newId = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      await chrome.storage.local.set({ sessionId: newId });
      return newId;
    }
    return stored.sessionId;
  }

  async loadConfig() {
    const stored = await chrome.storage.sync.get('extensionConfig');
    this.config = stored.extensionConfig || {};
  }
}

