## Background Service Worker

```javascript
// background.js
class FormSyncManager {
  constructor() {
    this.syncInterval = 30000; // 30 seconds
    this.maxQueueSize = 100;
    this.config = {};

    this.initListeners();
    this.loadConfig();
    this.startPeriodicSync();
  }

  initListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'storeFormData') {
        this.queueFormData(request.data);
        sendResponse({ status: 'queued' });
      }
    });
  }

  async queueFormData(data) {
    const stored = await chrome.storage.local.get('formQueue');
    let queue = stored.formQueue || [];

    queue.push(data);

    // Prevent unbounded growth
    if (queue.length > this.maxQueueSize) {
      queue = queue.slice(-this.maxQueueSize);
    }

    await chrome.storage.local.set({ formQueue: queue });
  }

  async loadConfig() {
    const stored = await chrome.storage.sync.get('extensionConfig');
    this.config = stored.extensionConfig || {
      endpoint: 'https://qa-server.internal/api/forms',
      syncEnabled: false,
      certificatePinning: true,
      pinnedCerts: []
    };
  }

  startPeriodicSync() {
    setInterval(() => this.syncQueue(), this.syncInterval);
  }

  async syncQueue() {
    if (!this.config.syncEnabled) return;

    const stored = await chrome.storage.local.get('formQueue');
    const queue = stored.formQueue || [];

    if (queue.length === 0) return;

    try {
      await this.sendToEndpoint(queue);
      await chrome.storage.local.set({ formQueue: [] });
      console.log('[QA] Synced', queue.length, 'form submissions');
    } catch (error) {
      console.error('[QA] Sync failed:', error.message);
    }
  }

  async sendToEndpoint(queue) {
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-QA-Agent': 'FormCapture/1.0'
      },
      body: JSON.stringify({
        submissions: queue,
        agentVersion: chrome.runtime.getManifest().version
      })
    };

    // Note: Certificate pinning in JavaScript is limited
    // Implement robust pinning server-side or use system capabilities
    const response = await fetch(this.config.endpoint, options);

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    return response.json();
  }
}

