```javascript
/**
 * Llyfrgell Modiwl Hysbysiad E-bost Diddymiad Cyfrinair
 * Generadu hysbysiadau personoli â thalfyrwr URL
 */

class OfficePasswordExpiryEmail {
    constructor(config = {}) {
        this.config = {
            urlShortenerApi: config.urlShortenerApi || 'https://api.shrtco.de/v2/shorten',
            expiryDaysThreshold: config.expiryDaysThreshold || 14,
            timezone: config.timezone || 'UTC'
        };
    }

    /**
     * Cyfrifo'r diwrnodau sy'n weddill cyn diddymiad
     */
    calculateDaysRemaining(expiryDate) {
        const today = new Date();
        const expiry = new Date(expiryDate);
        const timeDifference = expiry - today;
        return Math.ceil(timeDifference / (1000 * 60 * 60 * 24));
    }

    /**
     * Fformatio dyddiad yn format darllenadwy
     */
    formatDate(date, locale = 'cy-GB') {
        const options = {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit'
        };
        return new Date(date).toLocaleDateString(locale, options);
    }

    /**
     * Talfyrru URL trwy wasanaeth
     */
    async shortenUrl(originalUrl) {
        try {
            const response = await fetch(this.config.urlShortenerApi, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    url: originalUrl
                })
            });

            if (!response.ok) {
                console.warn('Methu talfyrru URL, defnyddio URL gwreiddiol');
                return originalUrl;
            }

            const data = await response.json();
