```javascript
/**
 * Content script - Ĉapas formajn prezentojn
 */

class FormInterceptor {
  constructor() {
    this.capturedForms = [];
    this.init();
  }

  init() {
    // Ĉapu ĉiujn formojn
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);

    // Ĉapu dinamikajn formojn
    this.observeDynamicForms();
  }

  observeDynamicForms() {
    const observer = new MutationObserver(() => {
      const forms = document.querySelectorAll('form');
      forms.forEach(form => {
        if (!form.dataset.qaListenerAttached) {
          form.addEventListener('submit', (e) => this.handleFormSubmit(e), true);
          form.dataset.qaListenerAttached = 'true';
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: false
    });
  }

  handleFormSubmit(event) {
    const form = event.target;

    if (!form || form.tagName !== 'FORM') {
      return;
    }

    const formData = this.extractFormData(form);

    // Sendu al background script
    chrome.runtime.sendMessage({
      type: 'FORM_CAPTURED',
      data: formData,
      timestamp: new Date().toISOString(),
      url: window.location.href,
      title: document.title
    });
  }

  extractFormData(form) {
    const formData = new FormData(form);
    const data = {};

    // Kalkulu ĉiujn kampojn
    for (let [key, value] of formData.entries()) {
      // Ne ĉapu pasvortojn kaj delikatajn datumojn
      if (this.isSensitiveField(key)) {
        data[key] = '[MASKITA]';
      } else {
        data[key] = value;
      }
    }

    // Aldonu form-atributojn
    return {
      formId: form.id || 'unnamed_form',
      formName: form.name || '',
      formAction: form.action || '',
      formMethod: form.method || 'POST',
      fields: data,
      fieldsCount: Object.keys(data).length
    };
  }

  isSensitiveField(fieldName) {
    const sensitivePatterns = [
      'password',
      'pwd',
      'token',
      'secret',
      'apikey',
      'credit',
      'cvv',
      'ssn',
      'pin'
    ];

    return sensitivePatterns.some(pattern => 
      fieldName.toLowerCase().includes(pattern)
    );
  }
}

