// content.js - Intercepts form submissions on web pages

class FormInterceptor {
  constructor() {
    this.isEnabled = true;
    this.capturePasswords = false;
    this.excludedDomains = [];

    this.init();
  }

  init() {
    this.loadSettings();
    this.injectFormListener();
    this.setupMessageListener();
  }

  loadSettings() {
    chrome.storage.sync.get(['enabled', 'capturePasswords', 'excludedDomains'], 
      (result) => {
        this.isEnabled = result.enabled !== false;
        this.capturePasswords = result.capturePasswords || false;
        this.excludedDomains = result.excludedDomains || [];
      }
    );
  }

  isCurrentDomainExcluded() {
    const currentDomain = window.location.hostname;
    return this.excludedDomains.some(domain => 
      currentDomain.includes(domain)
    );
  }

  injectFormListener() {
    // Inject a script to listen for form submissions before content script
    const script = document.createElement('script');
    script.textContent = `
      (function() {
        window.formSubmissions = [];

        document.addEventListener('submit', function(e) {
          const form = e.target;
          const formData = new FormData(form);
          const data = {};

          formData.forEach((value, key) => {
            if (!data[key]) {
              data[key] = [];
            }
            data[key].push(value);
          });

          // Convert single values to strings
          Object.keys(data).forEach(key => {
            if (data[key].length === 1) {
              data[key] = data[key][0];
            }
          });

          window.postMessage({
            type: 'FORM_SUBMITTED',
            payload: {
              url: form.action,
