      if (sensitive.some(s => key.toLowerCase().includes(s))) {
        if (!this.capturePasswords) {
          sanitized[key] = '[REDACTED]';
        }
      }
    });

    return sanitized;
  }

  generateId() {
    return `form_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
