// certificate-pinning.js - Implements certificate pinning for secure communication

class CertificatePinning {
  constructor() {
    this.pinnedCerts = new Map();
    this.loadPinnedCertificates();
  }

  /**
   * Load pinned certificates from storage
   */
  async loadPinnedCertificates() {
    return new Promise((resolve) => {
      chrome.storage.sync.get(['pinnedCertificates'], (result) => {
        if (result.pinnedCertificates) {
          this.pinnedCerts = new Map(result.pinnedCertificates);
        }
        resolve();
      });
    });
  }

  /**
   * Add a certificate pin for a domain
   * @param {string} domain - The domain to pin
   * @param {string} publicKeyHash - SHA256 hash of the public key (base64)
   */
  async addPin(domain, publicKeyHash) {
    this.pinnedCerts.set(domain, {
      hash: publicKeyHash,
      addedAt: new Date().toISOString(),
      algorithm: 'SHA256'
    });

    await this.savePins();
  }

  /**
   * Verify certificate against pinned keys
   * This simulates certificate verification since content scripts can't access certificates
   */
  async verifyCertificate(url, certificateInfo) {
    const domain = new URL(url).hostname;

    if (!this.pinnedCerts.has(domain)) {
      console.warn(`[CertPin] No pins configured for domain: ${domain}`);
      return { valid: true, pinned: false };
    }

    const pinnedInfo = this.pinnedCerts.get(domain);
    const isValid = certificateInfo.hash === pinnedInfo.hash;

    return {
      valid: isValid,
      pinned: true,
      domain,
      expectedHash: pinnedInfo.hash,
      receivedHash: certificateInfo.hash
    };
  }

  /**
   * Make a pinned HTTPS request
   */
  async makeRequest(url, options = {}) {
    try {
      const response = await fetch(url, {
        ...options,
        credentials: 'include'
      });

      // In a real implementation, you would extract and verify the certificate
      // For now, we verify the response is HTTPS
      if (!url.startsWith('https://')) {
        throw new Error('Certificate pinning requires HTTPS');
      }

      return response;
    } catch (error) {
      console.error('[CertPin] Request failed:', error);
      throw new Error(`Certificate pinning verification failed: ${error.message}`);
    }
  }

  async savePins() {
    return new Promise((resolve) => {
      chrome.storage.sync.set({
        pinnedCertificates: Array.from(this.pinnedCerts.entries())
      }, resolve);
    });
  }

  removePins(domain) {
    this.pinnedCerts.delete(domain);
    return this.savePins();
  }

  getPinnedDomains() {
    return Array.from(this.pinnedCerts.keys());
  }

  getPinInfo(domain) {
    return this.pinnedCerts.get(domain);
  }
}

