/**
 * Local Storage Management for Form Submissions
 */

class StorageManager {
  constructor() {
    this.storageKey = 'formSubmissions';
    this.maxEntries = 1000;
    this.maxStorageSize = 5242880; // 5MB
  }

  /**
   * Save form submission data
   * @param {Object} formData - Form submission data
   * @returns {Promise<Object>} Saved submission with ID and timestamp
   */
  async saveSubmission(formData) {
    try {
      const submission = {
        id: this.generateId(),
        timestamp: new Date().toISOString(),
        url: formData.url,
        formName: formData.formName || 'unnamed',
        fields: formData.fields,
        synced: false,
        syncAttempts: 0,
        lastSyncAttempt: null,
        metadata: {
          userAgent: navigator.userAgent,
          platform: navigator.platform,
          language: navigator.language
        }
      };

      const submissions = await this.getSubmissions();
      submissions.push(submission);

      // Enforce maximum entries
      if (submissions.length > this.maxEntries) {
        submissions.splice(0, submissions.length - this.maxEntries);
      }

      await this.setSubmissions(submissions);

      console.log(`Form submission saved: ${submission.id}`);
      return submission;
    } catch (error) {
      console.error('Error saving submission:', error);
      throw error;
    }
  }

  /**
   * Get all stored submissions
   * @returns {Promise<Array>}
   */
  async getSubmissions() {
    return new Promise((resolve, reject) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        if (chrome.runtime.lastError) {
          reject(chrome.runtime.lastError);
        } else {
          resolve(result[this.storageKey] || []);
        }
      });
    });
  }

  /**
   * Get unsynced submissions
   * @returns {Promise<Array>}
   */
  async getUnsyncedSubmissions() {
    const submissions = await this.getSubmissions();
    return submissions.filter(sub => !sub.synced);
  }

  /**
   * Get submissions by status
   * @param {boolean} synced - Filter by sync status
   * @returns {Promise<Array>}
   */
  async getSubmissionsByStatus(synced) {
    const submissions = await this.getSubmissions();
    return submissions.filter(sub => sub.synced === synced);
  }

  /**
   * Update submission sync status
   * @param {string} submissionId
   * @param {Object} updateData
   * @returns {Promise<Object>}
   */
  async updateSubmission(submissionId, updateData) {
    try {
      const submissions = await this.getSubmissions();
      const index = submissions.findIndex(sub => sub.id === submissionId);

      if (index === -1) {
        throw new Error(`Submission not found: ${submissionId}`);
      }

      submissions[index] = {
        ...submissions[index],
        ...updateData
      };

      await this.setSubmissions(submissions);
      return submissions[index];
    } catch (error) {
      console.error('Error updating submission:', error);
      throw error;
    }
  }

  /**
   * Mark submission as synced
   * @param {string} submissionId
   * @returns {Promise<Object>}
   */
  async markAsSynced(submissionId) {
    return this.updateSubmission(submissionId, {
      synced: true,
      syncedAt: new Date().toISOString()
    });
  }

  /**
   * Delete submission
   * @param {string} submissionId
   * @returns {Promise<void>}
   */
  async deleteSubmission(submissionId) {
    try {
      let submissions = await this.getSubmissions();
      submissions = submissions.filter(sub => sub.id !== submissionId);
      await this.setSubmissions(submissions);
    } catch (error) {
      console.error('Error deleting submission:', error);
      throw error;
    }
  }

  /**
   * Clear all submissions
   * @returns {Promise<void>}
   */
  async clearAllSubmissions() {
    return chrome.storage.local.remove([this.storageKey]);
  }

  /**
   * Export submissions as JSON
   * @returns {Promise<string>}
   */
  async exportSubmissions() {
    const submissions = await this.getSubmissions();
    return JSON.stringify(submissions, null, 2);
  }

  /**
   * Get storage statistics
   * @returns {Promise<Object>}
   */
  async getStorageStats() {
    const submissions = await this.getSubmissions();
    const synced = submissions.filter(sub => sub.synced).length;
    const unsynced = submissions.filter(sub => !sub.synced).length;

    return {
      totalSubmissions: submissions.length,
      syncedSubmissions: synced,
      unsyncedSubmissions: unsynced,
      estimatedSize: JSON.stringify(submissions).length,
      maxSize: this.maxStorageSize
    };
  }

  /**
   * Set submissions
   * @private
   * @param {Array} submissions
   * @returns {Promise<void>}
   */
  setSubmissions(submissions) {
    return new Promise((resolve, reject) => {
      chrome.storage.local.set(
        { [this.storageKey]: submissions },
        () => {
          if (chrome.runtime.lastError) {
            reject(chrome.runtime.lastError);
          } else {
            resolve();
          }
        }
      );
    });
  }

  /**
   * Generate unique ID
   * @private
   * @returns {string}
   */
  generateId() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Sanitize form data (remove sensitive fields)
   * @param {Object} fields
   * @returns {Object}
   */
  sanitizeFormData(fields) {
    const sensitivePatterns = [
      /password/i,
      /credit.?card/i,
      /cvv/i,
      /ssn/i,
      /secret/i,
      /token/i,
      /api.?key/i
    ];

    const sanitized = {};

    for (const [key, value] of Object.entries(fields)) {
      const isSensitive = sensitivePatterns.some(pattern => 
        pattern.test(key)
      );

      sanitized[key] = isSensitive ? '[REDACTED]' : value;
    }

    return sanitized;
  }
}

