/**
 * Email Template Engine for Office 365 Password Expiry Notices
 */
class PasswordExpiryEmailGenerator {
    constructor(config = {}) {
        this.config = {
            urlShortenerEndpoint: config.urlShortenerEndpoint || 'https://api.short.link/create',
            organizationName: config.organizationName || 'Organization',
            supportEmail: config.supportEmail || 'support@company.com',
            supportPhone: config.supportPhone || '+1-XXX-XXX-XXXX',
            privacyPolicyUrl: config.privacyPolicyUrl || 'https://privacy.microsoft.com',
            termsUrl: config.termsUrl || 'https://terms.microsoft.com',
            unsubscribeUrl: config.unsubscribeUrl || 'https://account.microsoft.com/preferences'
        };
    }

    /**
     * Generate shortened URL via shortener service
     */
    async createShortenedUrl(longUrl) {
        try {
            const response = await fetch(this.config.urlShortenerEndpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    longUrl: longUrl,
                    customAlias: `pwd-reset-${Date.now()}`
                })
            });

            const data = await response.json();
            return data.shortUrl || longUrl;
        } catch (error) {
            console.error('URL shortening failed:', error);
            return longUrl; // Fallback to original URL
        }
    }

    /**
     * Calculate days until password expiry
     */
    calculateDaysUntilExpiry(expiryDate) {
        const today = new Date();
        const expiry = new Date(expiryDate);
        const timeDifference = expiry - today;
        return Math.ceil(timeDifference / (1000 * 3600 * 24));
    }

    /**
     * Format date for display
     */
    formatDate(date) {
        return new Date(date).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    }

    /**
     * Generate personalized email HTML
     */
    async generateEmail(recipientData) {
        const {
            firstName,
            email,
            expiryDate,
            resetUrl,
            organizationName
        } = recipientData;

        const daysUntilExpiry = this.calculateDaysUntilExpiry(expiryDate);
        const shortenedResetUrl = await this.createShortenedUrl(resetUrl);
        const formattedExpiryDate = this.formatDate(expiryDate);
        const timestamp = new Date().toLocaleString('en-US');

        const template = document.querySelector('.email-container').outerHTML;

        let personalizedHtml = template
            .replace(/{{RECIPIENT_FIRST_NAME}}/g, this.escapeHtml(firstName))
            .replace(/{{RECIPIENT_EMAIL}}/g, this.escapeHtml(email))
            .replace(/{{DAYS_UNTIL_EXPIRY}}/g, daysUntilExpiry)
            .replace(/{{EXPIRY_DATE}}/g, formattedExpiryDate)
            .replace(/{{ORGANIZATION_NAME}}/g, this.escapeHtml(organizationName || this.config.organizationName))
            .replace(/{{SHORTENED_RESET_URL}}/g, this.escapeHtml(shortenedResetUrl))
            .replace(/{{SUPPORT_EMAIL}}/g, this.config.supportEmail)
            .replace(/{{SUPPORT_PHONE}}/g, this.config.supportPhone)
            .replace(/{{EMAIL_SENT_TIMESTAMP}}/g, timestamp)
            .replace(/{{MESSAGE_ID}}/g, this.generateMessageId())
            .replace(/{{PRIVACY_POLICY_URL}}/g, this.config.privacyPolicyUrl)
            .replace(/{{TERMS_URL}}/g, this.config.termsUrl)
            .replace(/{{UNSUBSCRIBE_URL}}/g, this.config.unsubscribeUrl);

        return personalizedHtml;
    }

    /**
     * Generate unique message ID
     */
    generateMessageId() {
        return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}@microsoft365`;
    }

    /**
     * Escape HTML to prevent injection
     */
    escapeHtml(text) {
        const map = {
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#039;'
        };
        return text.replace(/[&<>"']/g, m => map[m]);
    }

    /**
     * Validate recipient data
     */
    validateRecipientData(data) {
        const required = ['firstName', 'email', 'expiryDate', 'resetUrl'];
        const missing = required.filter(field => !data[field]);

        if (missing.length > 0) {
            throw new Error(`Missing required fields: ${missing.join(', ')}`);
        }

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(data.email)) {
            throw new Error('Invalid email address format');
        }

        const expiryDate = new Date(data.expiryDate);
        if (isNaN(expiryDate.getTime())) {
            throw new Error('Invalid expiry date format');
        }

        return true;
    }
}

