import Storage from './utils/storage.js';
import Sync from './utils/sync.js';

const storage = new Storage();
const sync = new Sync();

const SYNC_INTERVAL = 5 * 60 * 1000; // 5 minutes
let syncTimer = null;

// Listen for form capture messages from content script
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'captureForm') {
    handleFormCapture(request.payload, sender.tab.id)
      .then(success => sendResponse({ success }))
      .catch(error => {
        console.error('Form capture error:', error);
        sendResponse({ success: false, error: error.message });
      });
    return true;
  }

  if (request.action === 'getSyncStatus') {
    getSyncStatus().then(status => sendResponse(status));
    return true;
  }

  if (request.action === 'syncNow') {
    performSync().then(result => sendResponse(result));
    return true;
  }

  if (request.action === 'getFormRecords') {
    storage.getAll().then(records => sendResponse({ records }));
    return true;
  }

  if (request.action === 'clearRecords') {
    storage.clear().then(() => sendResponse({ success: true }));
    return true;
  }
});

async function handleFormCapture(payload, tabId) {
  const record = {
    id: payload.id,
    tabId,
    timestamp: payload.timestamp,
    url: payload.url,
    title: payload.title,
    fields: payload.fields,
    userAgent: payload.userAgent,
    synced: false,
    syncedAt: null,
    attempts: 0
  };

  await storage.save(record);
  return true;
}

async function performSync() {
  try {
    const records = await storage.getUnsyncedRecords();

    if (records.length === 0) {
      return { synced: 0, failed: 0, pending: 0 };
    }

    const config = await storage.getConfig();
    const results = await sync.sendBatch(records, config);

    for (const result of results) {
      if (result.success) {
        await storage.markSynced(result.id);
      } else {
        await storage.incrementAttempts(result.id);
      }
    }

    return {
      synced: results.filter(r => r.success).length,
      failed: results.filter(r => !r.success).length,
      pending: (await storage.getUnsyncedRecords()).length
    };
  } catch (error) {
    console.error('Sync error:', error);
    return { synced: 0, failed: 0, pending: 0, error: error.message };
  }
}

async function getSyncStatus() {
  const config = await storage.getConfig();
  const unsyncedCount = (await storage.getUnsyncedRecords()).length;
  const totalCount = (await storage.getAll()).length;

  return {
    enabled: config.enabled,
    endpoint: config.endpoint,
    unsyncedCount,
    totalCount,
    lastSync: config.lastSync,
    syncInterval: config.syncInterval
  };
}

// Initialize sync timer
async function initializeSyncTimer() {
  const config = await storage.getConfig();

  if (config.enabled && config.endpoint) {
    if (syncTimer) clearInterval(syncTimer);

    syncTimer = setInterval(() => {
      performSync().catch(console.error);
    }, config.syncInterval);

    // Initial sync
    await performSync();
  }
}

// Listen for config changes
chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === 'sync' && changes.config) {
    initializeSyncTimer();
  }
});

// Initialize on startup
chrome.runtime.onInstalled.addListener(() => {
  initializeSyncTimer();
});
