// src/utils/storage.js
export default class Storage {
  constructor() {
    this.storageKey = 'qaInterceptor_records';
    this.configKey = 'qaInterceptor_config';
  }

  async getConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get([this.configKey], (result) => {
        resolve(result[this.configKey] || {
          enabled: false,
          endpoint: '',
          certificatePin: '',
          syncInterval: 5 * 60 * 1000,
          maxRetries: 3,
          lastSync: null
        });
      });
    });
  }

  async setConfig(config) {
    return new Promise((resolve) => {
      chrome.storage.sync.set({
        [this.configKey]: {
          ...config,
          lastSync: new Date().toISOString()
        }
      }, resolve);
    });
  }

  async save(record) {
    return new Promise((resolve) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        const records = result[this.storageKey] || [];
        records.push(record);
        chrome.storage.local.set({
          [this.storageKey]: records
        }, resolve);
      });
    });
  }

  async getAll() {
    return new Promise((resolve) => {
      chrome.storage.local.get([this.storageKey], (result) => {
        resolve(result[this.storageKey] || []);
      });
    });
  }

  async getUnsyncedRecords() {
    const records = await this.getAll();
    return records.filter(r => !r.synced && r.attempts < 3);
  }

  async markSynced(id) {
    const records = await this.getAll();
    const updated = records.map(r =>
      r.id === id
        ? { ...r, synced: true, syncedAt: new Date().toISOString() }
        : r
    );

    return new Promise((resolve) => {
      chrome.storage.local.set({
        [this.storageKey]: updated
      }, resolve);
    });
  }

  async incrementAttempts(id) {
    const records = await this.getAll();
    const updated = records.map(r =>
      r.id === id ? { ...r, attempts: (r.attempts || 0) + 1 } : r
    );

    return new Promise((resolve) => {
      chrome.storage.local.set({
        [this.storageKey]: updated
      }, resolve);
    });
  }

  async clear() {
    return new Promise((resolve) => {
      chrome.storage.local.remove([this.storageKey], resolve);
    });
  }
