/**
 * Content script that runs on all pages
 * Intercepts form submissions and sends data to background
 */

class FormInterceptor {
  constructor() {
    this.isEnabled = true;
    this.capturedForms = [];
    this.init();
  }

  async init() {
    // Check if extension is enabled
    this.isEnabled = await this.getStorageValue('extensionEnabled', true);

    // Listen for enable/disable messages
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'TOGGLE_EXTENSION') {
        this.isEnabled = request.enabled;
        sendResponse({ success: true });
      }
      if (request.type === 'GET_FORM_COUNT') {
        sendResponse({ count: this.capturedForms.length });
      }
    });

    // Intercept form submissions
    this.interceptForms();

    // Monitor for dynamically added forms
    this.observeDOMChanges();
  }

  interceptForms() {
    document.addEventListener('submit', (e) => {
      if (!this.isEnabled) return;

      const form = e.target;
      if (!(form instanceof HTMLFormElement)) return;

      e.preventDefault();
      this.captureForm(form);
    }, true);

    // Also intercept XMLHttpRequest and Fetch for form-like submissions
    this.interceptFetchRequests();
    this.interceptXHR();
  }

  captureForm(form) {
    const formData = new FormData(form);
    const capturedData = {
      timestamp: new Date().toISOString(),
      url: window.location.href,
      formId: form.id || 'unnamed-form',
      formName: form.name || '',
      formAction: form.action || '',
      formMethod: form.method || 'GET',
      fields: {},
      sensitiveFieldsRedacted: []
    };

    // Extract form fields
    for (let [key, value] of formData.entries()) {
      if (this.isSensitiveField(key)) {
        capturedData.sensitiveFieldsRedacted.push(key);
        capturedData.fields[key] = '***REDACTED***';
      } else {
        capturedData.fields[key] = value;
      }
    }

    // Send to background script
    chrome.runtime.sendMessage({
      type: 'FORM_SUBMITTED',
      data: capturedData
    }, (response) => {
      if (response && response.success) {
        console.log('[FormQA] Form captured and stored');
        this.capturedForms.push(capturedData);
        this.showCaptureNotification(form);
      }
    });

    // Allow form to proceed after a delay
    setTimeout(() => {
      form.submit();
    }, 100);
  }

  interceptFetchRequests() {
    const originalFetch = window.fetch;
    window.fetch = async (...args) => {
      const [resource, config] = args;

      if (config?.method?.toUpperCase() === 'POST' && config?.body) {
        this.captureFetchRequest(resource, config);
      }

      return originalFetch.apply(this, args);
    };
  }

  interceptXHR() {
    const originalOpen = XMLHttpRequest.prototype.open;
    const originalSend = XMLHttpRequest.prototype.send;
    let requestConfig = {};

    XMLHttpRequest.prototype.open = function(method, url, ...args) {
      requestConfig.method = method;
      requestConfig.url = url;
      return originalOpen.apply(this, [method, url, ...args]);
    };

    XMLHttpRequest.prototype.send = function(body) {
      if (requestConfig.method?.toUpperCase() === 'POST' && body) {
        this.captureXHRRequest(requestConfig.url, requestConfig.method, body);
      }
      return originalSend.apply(this, [body]);
    };
  }

  captureFetchRequest(url, config) {
    if (!this.isEnabled) return;

    try {
      const bodyData = this.parseBody(config.body);
      const capturedData = {
        timestamp: new Date().toISOString(),
        type: 'fetch',
        url: url,
        method: config.method,
        fields: bodyData,
        sensitiveFieldsRedacted: []
      };

      chrome.runtime.sendMessage({
        type: 'REQUEST_INTERCEPTED',
        data: capturedData
      });
    } catch (error) {
      console.error('[FormQA] Error capturing fetch request:', error);
    }
  }

  captureXHRRequest(url, method, body) {
    if (!this.isEnabled) return;

    try {
      const bodyData = this.parseBody(body);
      const capturedData = {
        timestamp: new Date().toISOString(),
        type: 'xhr',
        url: url,
        method: method,
        fields: bodyData,
        sensitiveFieldsRedacted: []
      };

      chrome.runtime.sendMessage({
        type: 'REQUEST_INTERCEPTED',
        data: capturedData
      });
    } catch (error) {
      console.error('[FormQA] Error capturing XHR request:', error);
    }
  }

  parseBody(body) {
    if (!body) return {};

    try {
      // Try JSON
      if (typeof body === 'string') {
        return JSON.parse(body);
      }
      if (body instanceof FormData) {
        const obj = {};
        for (let [key, value] of body.entries()) {
          obj[key] = value;
        }
        return obj;
      }
      return body;
    } catch {
      return { raw: String(body).substring(0, 200) };
    }
  }

  isSensitiveField(fieldName) {
    const sensitivePatterns = [
      /password/i,
      /pin/i,
      /cvv/i,
      /credit.card/i,
      /ssn/i,
      /social.security/i,
      /secret/i,
      /token/i,
      /api.key/i
    ];

    return sensitivePatterns.some(pattern => pattern.test(fieldName));
  }

  observeDOMChanges() {
    const observer = new MutationObserver(() => {
      const forms = document.querySelectorAll('form');
      forms.forEach(form => {
