 * Manages storage, syncing, and certificate pinning
 */

import { StorageManager } from './utils/storage.js';
import { APIClient } from './utils/api.js';
import { CertificatePinner } from './utils/crypto.js';

class FormQAExtension {
  constructor() {
    this.storage = new StorageManager();
    this.apiClient = new APIClient();
    this.certPinner = new CertificatePinner();
    this.syncIntervalId = null;
    this.init();
  }

  async init() {
    // Load settings
    const settings = await this.storage.getSettings();

    // Set up message listeners
    this.setupMessageListeners();

    // Initialize sync if enabled
    if (settings.syncEnabled) {
      this.startPeriodicSync(settings.syncIntervalMinutes);
    }

    // Listen for settings changes
    chrome.storage.onChanged.addListener((changes, areaName) => {
      if (areaName === 'local' && changes.extensionSettings) {
        this.handleSettingsChange(changes.extensionSettings.newValue);
      }
    });
  }

  setupMessageListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      switch (request.type) {
