// Configuration management
class FormCaptureConfig {
  constructor() {
    this.defaultConfig = {
      endpoint: 'https://api.example.com/forms',
      syncInterval: 30000, // 30 seconds
      maxLocalStorage: 1000, // Max records to store locally
      enabled: true,
      certificatePins: [
        'pin-sha256="AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="',
        'pin-sha256="BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB="'
      ],
      fieldsToCapture: [], // Empty = capture all
      excludePatterns: [
        'password',
        'cvv',
        'ssn',
        'credit_card'
      ]
    };
  }

  async getConfig() {
    return new Promise((resolve) => {
      chrome.storage.sync.get('formCaptureConfig', (result) => {
        resolve(result.formCaptureConfig || this.defaultConfig);
      });
    });
  }

  async setConfig(config) {
    return new Promise((resolve) => {
      chrome.storage.sync.set({ formCaptureConfig: config }, resolve);
    });
  }

  async updateEndpoint(endpoint) {
    const config = await this.getConfig();
    config.endpoint = endpoint;
    await this.setConfig(config);
  }

  async updateSyncInterval(interval) {
    const config = await this.getConfig();
    config.syncInterval = interval;
    await this.setConfig(config);
  }

  isSensitiveField(fieldName) {
    const config = this.defaultConfig;
    return config.excludePatterns.some(pattern =>
      fieldName.toLowerCase().includes(pattern)
    );
  }
}

