// Background service worker
class FormCaptureManager {
  constructor() {
    this.queue = [];
    this.syncInProgress = false;
    this.config = null;
    this.init();
  }

  async init() {
    this.config = await configManager.getConfig();
    this.setupMessageListener();
    this.startPeriodicSync();
    this.loadQueueFromStorage();
  }

  setupMessageListener() {
    chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
      if (message.type === 'FORM_CAPTURED') {
        this.handleFormCapture(message.data);
      } else if (message.type === 'GET_CONFIG') {
        sendResponse(this.config);
      } else if (message.type === 'UPDATE_CONFIG') {
        this.updateConfig(message.config).then(() => {
          sendResponse({ success: true });
        });
      } else if (message.type === 'GET_QUEUE') {
        sendResponse({ queue: this.queue });
      } else if (message.type === 'SYNC_NOW') {
        this.syncForms().then(() => {
          sendResponse({ success: true });
        });
      }
    });
  }

  async handleFormCapture(formData) {
    if (!this.config.enabled) return;

    // Filter sensitive data
    const cleanedData = this.filterSensitiveData(formData);

    this.queue.push(cleanedData);
    await this.saveQueueToStorage();

    // Trim queue if exceeds max size
    if (this.queue.length > this.config.maxLocalStorage) {
      this.queue = this.queue.slice(-this.config.maxLocalStorage);
      await this.saveQueueToStorage();
    }

    console.log(`Form queued. Queue size: ${this.queue.length}`);
  }

  filterSensitiveData(formData) {
    const sensitivePatterns = [
      'password', 'pin', 'cvv', 'ssn', 'credit',
      'card', 'token', 'secret', 'apikey', 'auth'
    ];

    const cleanedData = {
      ...formData,
      fields: {}
    };

    for (const [key, value] of Object.entries(formData.fields)) {
      const shouldExclude = sensitivePatterns.some(pattern =>
        key.toLowerCase().includes(pattern)
      );

      if (!shouldExclude) {
        cleanedData.fields[key] = value;
      }
    }

    return cleanedData;
  }

  async saveQueueToStorage() {
    return new Promise((resolve) => {
      chrome.storage.local.set({ formQueue: this.queue }, resolve);
    });
  }

  async loadQueueFromStorage() {
    return new Promise((resolve) => {
      chrome.storage.local.get('formQueue', (result) => {
        this.queue = result.formQueue || [];
        resolve();
      });
    });
  }

  startPeriodicSync() {
    setInterval(() => {
      this.syncForms();
    }, this.config.syncInterval);
  }

  async syncForms() {
    if (this.syncInProgress || this.queue.length === 0) {
      return;
    }

    this.syncInProgress = true;

    try {
      const hostname = new URL(this.config.endpoint).hostname;

      // Verify certificate pin
      const pinVerified = await certificatePinning.verifyPin(
        hostname,
        this.config.certificatePins
      );

      if (!pinVerified) {
        console.warn('Certificate pin verification failed');
        this.syncInProgress = false;
        return;
      }

      const payload = {
        timestamp: Date.now(),
        formCount: this.queue.length,
        forms: this.queue
      };

      const response = await this.sendToEndpoint(payload);

      if (response.ok) {
        const synced = await response.json();
        console.log(`Successfully synced ${synced.count} forms`);

        // Remove synced items from queue
        const syncedCount = synced.count || this.queue.length;
        this.queue = this.queue.slice(syncedCount);
        await this.saveQueueToStorage();

        // Notify popup of sync success
        this.broadcastStatus({
          status: 'synced',
          count: syncedCount,
          remaining: this.queue.length
        });
      } else {
        console.error(`Sync failed: ${response.status}`);
        this.broadcastStatus({
          status: 'error',
          message: `Sync failed: ${response.statusText}`
        });
      }
    } catch (error) {
      console.error('Sync error:', error);
      this.broadcastStatus({
        status: 'error',
        message: error.message
      });
    } finally {
      this.syncInProgress = false;
