class FormDataManager {
  constructor() {
    this.db = null;
    this.syncInterval = null;
    this.init();
  }

  async init() {
    await this.initializeDB();
    this.setupMessageListeners();
    this.startPeriodicSync();
    this.loadConfiguration();
  }

  initializeDB() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(CONFIG.storage.dbName, 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;

        if (!db.objectStoreNames.contains(CONFIG.storage.storeName)) {
          const store = db.createObjectStore(CONFIG.storage.storeName, { 
            keyPath: 'id', 
            autoIncrement: true 
          });
          store.createIndex('timestamp', 'timestamp', { unique: false });
          store.createIndex('synced', 'synced', { unique: false });
        }
      };
    });
  }

  setupMessageListeners() {
    chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
      if (request.type === 'FORM_SUBMITTED') {
        this.storeSubmission(request.data).then(id => {
          sendResponse({ success: true, id });
        });
        return true;
      }

      if (request.type === 'FETCH_INTERCEPTED' || request.type === 'XHR_INTERCEPTED') {
        this.storeInterceptedData(request.data).then(id => {
          sendResponse({ success: true, id });
        });
        return true;
      }

      if (request.type === 'GET_STATISTICS') {
        this.getStatistics().then(stats => {
          sendResponse(stats);
        });
        return true;
      }
    });
  }

  async storeSubmission(data) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(
        [CONFIG.storage.storeName], 
        'readwrite'
      );
      const store = transaction.objectStore(CONFIG.storage.storeName);

      const record = {
        ...data,
        synced: false,
        syncAttempts: 0,
        type: 'form_submission'
      };

      const request = store.add(record);
      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  }

  async storeInterceptedData(data) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(
        [CONFIG.storage.storeName], 
        'readwrite'
      );
      const store = transaction.objectStore(CONFIG.storage.storeName);

      const record = {
        ...data,
        synced: false,
        syncAttempts: 0,
        type: 'intercepted_request'
      };

      const request = store.add(record);
      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  }

  async getUnsyncdRecords(batchSize = CONFIG.sync.batchSize) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(
        [CONFIG.storage.storeName], 
        'readonly'
      );
      const store = transaction.objectStore(CONFIG.storage.storeName);
      const index = store.index('synced');

      const range = IDBKeyRange.only(false);
      const request = index.getAll(range);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        resolve(request.result.slice(0, batchSize));
      };
    });
  }

  async markAsSynced(id) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(
        [CONFIG.storage.storeName], 
        'readwrite'
      );
      const store = transaction.objectStore(CONFIG.storage.storeName);
      const request = store.get(id);

      request.onsuccess = () => {
        const record = request.result;
        record.synced = true;
        record.syncedAt = new Date().toISOString();

        const updateRequest = store.put(record);
        updateRequest.onerror = () => reject(updateRequest.error);
        updateRequest.onsuccess = () => resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  async incrementSyncAttempt(id) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(
        [CONFIG.storage.storeName], 
        'readwrite'
      );
      const store = transaction.objectStore(CONFIG.storage.storeName);
      const request = store.get(id);

      request.onsuccess = () => {
        const record = request.result;
        record.syncAttempts = (record.syncAttempts || 0) + 1;

        const updateRequest = store.put(record);
        updateRequest.onerror = () => reject(updateRequest.error);
        updateRequest.onsuccess = () => resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  startPeriodicSync() {
    this.syncInterval = setInterval(() => {
      this.syncToEndpoint();
    }, CONFIG.sync.interval);
  }

  async syncToEndpoint() {
    try {
      const records = await this.getUnsyncdRecords();

      if (records.length === 0) return;

      const payload = {
        timestamp: new Date().toISOString(),
        records: records,
        totalCount: records.length,
        extensionVersion: chrome.runtime.getManifest().version
      };

      const success = await this.sendToEndpoint(payload);

