// Form interception and local capture
class FormInterceptor {
  constructor() {
    this.formData = [];
    this.init();
  }

  init() {
    document.addEventListener('submit', (e) => this.handleFormSubmit(e), true);
    this.setupAjaxInterception();
  }

  handleFormSubmit(event) {
    const form = event.target;
    const formFields = this.extractFormData(form);

    const submission = {
      id: this.generateId(),
      timestamp: new Date().toISOString(),
      url: window.location.href,
      formName: form.name || form.id || 'unnamed',
      fields: formFields,
      method: form.method.toUpperCase() || 'POST',
      action: form.action || ''
    };

    this.storeLocally(submission);
    chrome.runtime.sendMessage({
      type: 'FORM_SUBMITTED',
      data: submission
    });
  }

  extractFormData(form) {
    const fields = {};
    const formData = new FormData(form);

    for (let [key, value] of formData.entries()) {
      if (!key.includes('password') && !key.includes('token')) {
        fields[key] = value;
      }
    }

    form.querySelectorAll('input, textarea, select').forEach(field => {
      if (field.name && !field.name.includes('password')) {
        fields[field.name] = field.value;
      }
    });

    return fields;
  }

  setupAjaxInterception() {
    const originalFetch = window.fetch;
    window.fetch = async (...args) => {
      const [resource, config] = args;

      if (config?.method === 'POST' || config?.method === 'PUT') {
        try {
          const body = config.body;
          if (body && typeof body === 'string') {
            const submission = {
              id: this.generateId(),
              timestamp: new Date().toISOString(),
              url: window.location.href,
              type: 'FETCH_REQUEST',
              method: config.method,
              endpoint: resource,
              payload: JSON.parse(body)
            };
            this.storeLocally(submission);
          }
        } catch (e) {
          console.log('Could not parse fetch body');
        }
      }

      return originalFetch.apply(window, args);
    };
  }

  storeLocally(submission) {
    chrome.storage.local.get('formSubmissions', (result) => {
      const submissions = result.formSubmissions || [];
      submissions.push(submission);

      // Keep last 500 submissions
      if (submissions.length > 500) {
        submissions.shift();
      }

      chrome.storage.local.set({ formSubmissions: submissions });
    });
  }

  generateId() {
    return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

new FormInterceptor();
