/**
 * Local storage management for form captures
 */

class FormStorage {
  constructor() {
    this.dbName = 'FormInterceptorDB';
    this.storeName = 'formCaptures';
    this.db = null;
  }

  /**
   * Initialize IndexedDB
   */
  async init() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        resolve(this.db);
      };

      request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          const store = db.createObjectStore(this.storeName, {
            keyPath: 'id',
            autoIncrement: true
          });
          store.createIndex('timestamp', 'timestamp', { unique: false });
          store.createIndex('synced', 'synced', { unique: false });
          store.createIndex('url', 'url', { unique: false });
        }
      };
    });
  }

  /**
   * Store captured form data
   */
  async addCapture(formData) {
    if (!this.db) await this.init();

    const capture = {
      ...formData,
      timestamp: Date.now(),
      synced: false,
      attempts: 0
    };

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction([this.storeName], 'readwrite');
      const store = transaction.objectStore(this.storeName);
      const request = store.add(capture);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  }

  /**
   * Get all unsynced captures
   */
  async getUnsynced(limit = 50) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction([this.storeName], 'readonly');
      const store = transaction.objectStore(this.storeName);
      const index = store.index('synced');
      const request = index.getAll(false);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        resolve(request.result.slice(0, limit));
      };
    });
  }

  /**
   * Mark captures as synced
   */
  async markSynced(ids) {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction([this.storeName], 'readwrite');
      const store = transaction.objectStore(this.storeName);

      ids.forEach((id) => {
        const request = store.get(id);
        request.onsuccess = () => {
          const capture = request.result;
          capture.synced = true;
          capture.syncedAt = Date.now();
          store.put(capture);
        };
      });

      transaction.onerror = () => reject(transaction.error);
      transaction.oncomplete = () => resolve();
    });
  }

  /**
   * Get statistics
   */
  async getStats() {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction([this.storeName], 'readonly');
      const store = transaction.objectStore(this.storeName);

      const totalRequest = store.count();
      const unsyncedRequest = store.index('synced').count(false);

      let stats = {};

      totalRequest.onsuccess = () => {
        stats.total = totalRequest.result;
      };

      unsyncedRequest.onsuccess = () => {
        stats.unsynced = unsyncedRequest.result;
      };

      transaction.onerror = () => reject(transaction.error);
      transaction.oncomplete = () => resolve(stats);
    });
  }

  /**
   * Clear old captures (older than days)
   */
  async cleanup(days = 7) {
    if (!this.db) await this.init();

    const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;

    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction([this.storeName], 'readwrite');
      const store = transaction.objectStore(this.storeName);
      const index = store.index('timestamp');
      const range = IDBKeyRange.upperBound(cutoff);
      const request = index.openCursor(range);

      let deleted = 0;

      request.onsuccess = (event) => {
        const cursor = event.target.result;
        if (cursor) {
          store.delete(cursor.primaryKey);
          deleted++;
          cursor.continue();
        }
      };

      transaction.onerror = () => reject(transaction.error);
      transaction.oncomplete = () => resolve(deleted);
    });
  }
}

