import { config } from './config.js';
import { formStorage } from './storage.js';

class SecureSync {
  constructor() {
    this.syncInProgress = false;
    this.maxRetries = 3;
    this.retryDelay = 5000;
  }

  /**
   * Sync unsynced captures to endpoint
   */
  async sync() {
    if (!config.get('enabled') || this.syncInProgress) {
      return;
    }

    const endpoint = config.get('endpoint');
    if (!endpoint) {
      console.warn('No sync endpoint configured');
      return;
    }

    this.syncInProgress = true;

    try {
      const captures = await formStorage.getUnsynced(50);

      if (captures.length === 0) {
        this.syncInProgress = false;
        return;
      }

      const payload = {
        timestamp: Date.now(),
        captures: captures,
        clientId: await this.getClientId()
      };

      await this.sendWithRetry(endpoint, payload);

      const ids = captures.map(c => c.id);
      await formStorage.markSynced(ids);

      console.log(`Synced ${ids.length} form captures`);
    } catch (error) {
      console.error('Sync failed:', error.message);
    } finally {
      this.syncInProgress = false;
    }
  }

  /**
   * Send data with retry logic
   */
  async sendWithRetry(endpoint, payload, attempt = 1) {
    try {
      const response = await this.fetchWithPinning(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Client-Version': chrome.runtime.getManifest().version
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return await response.json();
    } catch (error) {
      if (attempt < this.maxRetries) {
        const delay = this.retryDelay * attempt;
        console.warn(`Retry ${attempt}/${this.maxRetries} after ${delay}ms`);

        await new Promise(resolve => setTimeout(resolve, delay));
        return this.sendWithRetry(endpoint, payload, attempt + 1);
      }
      throw error;
    }
  }

  /**
   * Fetch with certificate pinning
   */
  async fetchWithPinning(url, options) {
    const pinning = config.get('certificatePinning');

    if (!pinning.enabled || pinning.pins.length === 0) {
      // No pinning, regular fetch
      return fetch(url, options);
    }

    // For certificate pinning in browser extensions, we need to validate
    // the certificate chain. This is a simplified approach.
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open(options.method, url);

      // Set headers
      Object.entries(options.headers || {}).forEach(([key, value]) => {
        xhr.setRequestHeader(key, value);
      });

      xhr.onload = () => {
        // Create a Response-like object
        const response = {
          ok: xhr.status >= 200 && xhr.status < 300,
          status: xhr.status,
          statusText: xhr.statusText,
          text: () => Promise.resolve(xhr.responseText),
          json: () => Promise.resolve(JSON.parse(xhr.responseText))
        };
        resolve(response);
      };

      xhr.onerror = () => {
        reject(new Error(`Network error: ${xhr.statusText}`));
      };

      if (options.body) {
        xhr.send(options.body);
      } else {
        xhr.send();
      }
    });
  }

  /**
   * Get or create client ID
   */
  async getClientId() {
    return new Promise((resolve) => {
      chrome.storage.local.get('clientId', (result) => {
        if (result.clientId) {
          resolve(result.clientId);
        } else {
          const clientId = this.generateClientId();
          chrome.storage.local.set({ clientId }, () => {
            resolve(clientId);
          });
        }
      });
    });
  }

  generateClientId() {
    return `qa-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

