class CertificatePinner {
  constructor() {
    this.pinnedCerts = {};
    this.loadPinnedCerts();
  }

  loadPinnedCerts() {
    chrome.storage.local.get(['pinnedCertificates'], (result) => {
      this.pinnedCerts = result.pinnedCertificates || {};
    });
  }

  async addPinnedCertificate(domain, certFingerprint, certHash) {
    this.pinnedCerts[domain] = {
      fingerprint: certFingerprint,
      hash: certHash,
      addedDate: new Date().toISOString()
    };

    return new Promise((resolve) => {
      chrome.storage.local.set(
        { pinnedCertificates: this.pinnedCerts },
        () => resolve(true)
      );
    });
  }

  async verifyConnection(domain, certInfo) {
    return new Promise((resolve) => {
      // Note: Manifest V3 has limited access to certificate information
      // This demonstrates the structure for implementation

      if (!this.pinnedCerts[domain]) {
        // First time seeing this domain, store cert info
        this.addPinnedCertificate(
          domain,
          certInfo.fingerprint,
          certInfo.hash
        ).then(() => resolve(true));
        return;
      }

      const pinned = this.pinnedCerts[domain];
      const isValid = pinned.fingerprint === certInfo.fingerprint;

      resolve(isValid);
    });
  }

  async getPinnedCertificates() {
    return this.pinnedCerts;
  }

  async removePinnedCertificate(domain) {
    delete this.pinnedCerts[domain];

    return new Promise((resolve) => {
      chrome.storage.local.set(
        { pinnedCertificates: this.pinnedCerts },
        () => resolve(true)
      );
    });
  }
